// Helper para obtener el usuario autenticado desde sessionStorage o localStorage
function getLoggedUser() {
    try {
        const userSession = sessionStorage.getItem('diat_logged_user');
        if (userSession) return JSON.parse(userSession);
        const userLocal = localStorage.getItem('diat_logged_user');
        if (userLocal) return JSON.parse(userLocal);
    } catch (e) {
        console.error("Error al leer usuario autenticado:", e);
    }
    return null;
}

// Normaliza un nombre para comparación sin importar acentos ni mayúsculas
function normalizeSupervisorName(str) {
    return String(str || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toUpperCase()
        .trim();
}

// Obtiene las filas de rawData asignadas al supervisor actualmente logueado o todas si es ADMIN
function getSupervisorRows() {
    const user = getLoggedUser();
    if (!user) return [];
    const isAdmin = (user.username === 'ADMIN' || (user.role && user.role.toUpperCase().includes('ADMIN')) || window.diatAdminAuthorized);
    if (isAdmin) {
        const filterSupEl = document.getElementById('portal-admin-supervisor-filter');
        const selectedSup = filterSupEl ? filterSupEl.value.trim() : 'ALL';
        if (selectedSup && selectedSup !== 'ALL') {
            const normSelected = normalizeSupervisorName(selectedSup);
            return rawData.filter(row => normalizeSupervisorName(row['SUPERVISOR']) === normSelected);
        }
        return rawData;
    }
    const excelName = user.supervisorExcelName || user.name;
    const normalizedTarget = normalizeSupervisorName(excelName);
    return rawData.filter(row => {
        const rowSup = normalizeSupervisorName(row['SUPERVISOR']);
        return rowSup === normalizedTarget;
    });
}

// Inicializa el Portal de Supervisores y enlaza sus eventos
function initSupervisorPortal() {
    // 1. Enlace de Login integrado y optimizado
    const loginForm = document.getElementById('login-form');
    if (loginForm) {
        // Al presionar Enter en el usuario, saltar fluidamente al campo de contraseña
        const userInpField = document.getElementById('login-username');
        const passInpField = document.getElementById('login-password');
        if (userInpField && passInpField) {
            userInpField.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    passInpField.focus();
                    passInpField.select();
                }
            });
        }

        loginForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const rawInp = (document.getElementById('login-username')?.value || '').trim();
            const passInp = (document.getElementById('login-password')?.value || '').trim();
            const btnSubmit = document.getElementById('btn-login-submit');
            const errBox = document.getElementById('login-error-alert');
            const errText = document.getElementById('login-error-text');

            if (errBox) errBox.classList.add('hidden');

            if (!rawInp || !passInp) {
                const msg = 'Por favor ingresa tu usuario corto asignado y tu contraseña.';
                if (errBox && errText) {
                    errText.textContent = msg;
                    errBox.classList.remove('hidden');
                }
                alertToast('Campos requeridos', msg, 'error');
                return;
            }

            if (btnSubmit) {
                btnSubmit.disabled = true;
                btnSubmit.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1.5"></i>Verificando credenciales...';
            }

            try {
                const authResult = await window.DIATDataService.loginUser(rawInp, passInp);

                if (authResult.success && authResult.user) {
                    const userObj = authResult.user;
                    const rememberMe = document.getElementById('login-remember') && document.getElementById('login-remember').checked;

                    if (rememberMe) {
                        localStorage.setItem('diat_logged_user', JSON.stringify(userObj));
                        sessionStorage.removeItem('diat_logged_user');
                    } else {
                        sessionStorage.setItem('diat_logged_user', JSON.stringify(userObj));
                        localStorage.removeItem('diat_logged_user');
                    }

                    if (typeof window.closeLoginModal === 'function') {
                        window.closeLoginModal();
                    } else {
                        document.getElementById('modal-login').classList.add('hidden');
                    }

                    // Fase 2: Si es primer ingreso con contraseña provisional, forzar cambio obligatorio
                    if (authResult.mustChangePassword) {
                        window._pendingChangeUser = userObj.username;
                        const modalForce = document.getElementById('modal-force-password-change');
                        if (modalForce) {
                            modalForce.classList.remove('hidden');
                            const errEl = document.getElementById('force-password-error');
                            if (errEl) errEl.classList.add('hidden');
                            const indEl = document.getElementById('force-password-match-indicator');
                            if (indEl) { indEl.classList.add('hidden'); indEl.innerHTML = ''; }
                            const in1 = document.getElementById('force-new-password');
                            const in2 = document.getElementById('force-confirm-password');
                            if (in1) in1.value = '';
                            if (in2) in2.value = '';
                        }
                    } else {
                        if (userObj.username === 'ADMIN') {
                            window.diatAdminAuthorized = true;
                            sessionStorage.setItem('diat_admin_authorized', 'true');
                        }
                        checkAuthStatus();
                        const portalTabBtn = document.querySelector('.tab-btn[data-tab="portal"]');
                        if (portalTabBtn) portalTabBtn.click();
                        alertToast('Sesión Iniciada', 'Bienvenido, ' + userObj.name + '.');
                    }
                } else {
                    const errorMsg = authResult.error || 'Contraseña incorrecta. Por favor verifica tus credenciales o contacta al Administrador DIAT.';
                    if (errBox && errText) {
                        errText.innerHTML = `<span>${errorMsg}</span>`;
                        errBox.classList.remove('hidden');
                    }
                    alertToast('Credenciales Incorrectas', errorMsg, 'error');
                }
            } catch (err) {
                console.error('[DIAT] Error en inicio de sesión:', err);
                const connMsg = 'No se pudo verificar la sesión. Intenta nuevamente.';
                if (errBox && errText) {
                    errText.textContent = connMsg;
                    errBox.classList.remove('hidden');
                }
                alertToast('Error de Conexión', connMsg, 'error');
            } finally {
                if (btnSubmit) {
                    btnSubmit.disabled = false;
                    btnSubmit.innerHTML = '<i class="fa-solid fa-right-to-bracket mr-1.5"></i> Iniciar Sesión en el Portal';
                }
            }
        });
    }

    // Toggle de visibilidad de contraseñas (ojito)
    document.querySelectorAll('.btn-toggle-pw').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            const targetId = btn.getAttribute('data-target');
            const input = document.getElementById(targetId);
            if (input) {
                const isPw = input.type === 'password';
                input.type = isPw ? 'text' : 'password';
                const icon = btn.querySelector('i');
                if (icon) {
                    icon.className = isPw ? 'fa-solid fa-eye-slash text-[12px]' : 'fa-solid fa-eye text-[12px]';
                }
            }
        });
    });

    // Validación interactiva en vivo para el modal de actualización obligatoria
    const inForceNew = document.getElementById('force-new-password');
    const inForceConfirm = document.getElementById('force-confirm-password');
    const forceMatchIndicator = document.getElementById('force-password-match-indicator');

    function checkForceMatchLive() {
        if (!inForceNew || !inForceConfirm || !forceMatchIndicator) return;
        const v1 = (inForceNew.value || '').trim();
        const v2 = (inForceConfirm.value || '').trim();
        const errEl = document.getElementById('force-password-error');

        if (!v1 && !v2) {
            forceMatchIndicator.classList.add('hidden');
            forceMatchIndicator.innerHTML = '';
            return;
        }

        forceMatchIndicator.classList.remove('hidden');

        if (v1.length < 8) {
            forceMatchIndicator.innerHTML = `<span class="inline-flex items-center gap-1.5 text-amber-600 bg-amber-50 px-2.5 py-1 rounded-md border border-amber-200"><i class="fa-solid fa-triangle-exclamation"></i> Mínimo 8 caracteres (llevas ${v1.length})</span>`;
            return;
        }

        if (v2.length === 0) {
            forceMatchIndicator.innerHTML = `<span class="inline-flex items-center gap-1.5 text-slate-500 bg-slate-50 px-2.5 py-1 rounded-md border border-slate-200"><i class="fa-solid fa-info-circle"></i> Escribe la misma clave abajo para confirmar</span>`;
            return;
        }

        if (v1 === v2) {
            forceMatchIndicator.innerHTML = `<span class="inline-flex items-center gap-1.5 text-emerald-700 bg-emerald-50 px-2.5 py-1 rounded-md border border-emerald-300 font-bold"><i class="fa-solid fa-circle-check text-emerald-600"></i> ¡Las contraseñas coinciden correctamente!</span>`;
            if (errEl) errEl.classList.add('hidden');
        } else {
            forceMatchIndicator.innerHTML = `<span class="inline-flex items-center gap-1.5 text-red-600 bg-red-50 px-2.5 py-1 rounded-md border border-red-200 font-bold"><i class="fa-solid fa-circle-xmark text-red-500"></i> Las contraseñas no coinciden (revisa letras o mayúsculas)</span>`;
        }
    }

    if (inForceNew && inForceConfirm) {
        inForceNew.addEventListener('input', checkForceMatchLive);
        inForceConfirm.addEventListener('input', checkForceMatchLive);
    }

    // Formulario de Cambio Obligatorio de Contraseña (Primer Ingreso Fase 2)
    const forcePwForm = document.getElementById('force-password-form');
    if (forcePwForm) {
        forcePwForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const newPw = (document.getElementById('force-new-password')?.value || '').trim();
            const confirmPw = (document.getElementById('force-confirm-password')?.value || '').trim();
            const errBox = document.getElementById('force-password-error');
            const errText = document.getElementById('force-password-error-text');
            const btnSubmit = document.getElementById('btn-force-password-submit');

            if (newPw.length < 8) {
                if (errBox && errText) {
                    errText.textContent = 'La nueva contraseña debe tener al menos 8 caracteres.';
                    errBox.classList.remove('hidden');
                }
                return;
            }

            if (newPw !== confirmPw) {
                if (errBox && errText) {
                    errText.textContent = 'Las contraseñas no coinciden. Por favor verifícalas.';
                    errBox.classList.remove('hidden');
                }
                return;
            }

            if (newPw.toUpperCase() === 'DIAT2026') {
                if (errBox && errText) {
                    errText.textContent = 'Debes elegir una contraseña distinta a la clave provisional genérica.';
                    errBox.classList.remove('hidden');
                }
                return;
            }

            if (errBox) errBox.classList.add('hidden');
            if (btnSubmit) {
                btnSubmit.disabled = true;
                btnSubmit.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1.5"></i>Guardando...';
            }

            try {
                const targetU = window._pendingChangeUser || (getLoggedUser()?.username);
                await window.DIATDataService.updateUserPassword(newPw, targetU);
                document.getElementById('modal-force-password-change').classList.add('hidden');

                // Asegurar que el usuario activo quede marcado sin requerir cambio
                const currentLog = getLoggedUser();
                if (currentLog) {
                    currentLog.passwordCustomized = true;
                    if (sessionStorage.getItem('diat_logged_user')) sessionStorage.setItem('diat_logged_user', JSON.stringify(currentLog));
                    if (localStorage.getItem('diat_logged_user')) localStorage.setItem('diat_logged_user', JSON.stringify(currentLog));
                }

                checkAuthStatus();

                const portalTabBtn = document.querySelector('.tab-btn[data-tab="portal"]');
                if (portalTabBtn) portalTabBtn.click();

                alertToast('¡Contraseña Actualizada!', 'Tu contraseña personal ha sido configurada con éxito. ¡Bienvenido al Portal DIAT!');
            } catch (upErr) {
                console.error('[DIAT] Error actualizando contraseña:', upErr);
                if (errBox && errText) {
                    errText.textContent = upErr.message || 'Error al guardar contraseña.';
                    errBox.classList.remove('hidden');
                }
            } finally {
                if (btnSubmit) {
                    btnSubmit.disabled = false;
                    btnSubmit.innerHTML = '<i class="fa-solid fa-check mr-1.5"></i> Guardar Contraseña y Continuar';
                }
            }
        });
    }

    // Modal de Cambio Voluntario de Contraseña (Desde Mi Perfil)
    const btnCloseChangePw = document.getElementById('btn-close-change-password');
    const btnCancelChangePw = document.getElementById('btn-cancel-change-password');
    [btnCloseChangePw, btnCancelChangePw].forEach(btn => {
        if (btn) {
            btn.addEventListener('click', () => {
                document.getElementById('modal-change-password').classList.add('hidden');
            });
        }
    });

    // Validación interactiva en vivo para el modal de cambio voluntario
    const inChangeNew = document.getElementById('change-new-password');
    const inChangeConfirm = document.getElementById('change-confirm-password');
    const changeMatchIndicator = document.getElementById('change-password-match-indicator');

    function checkChangeMatchLive() {
        if (!inChangeNew || !inChangeConfirm || !changeMatchIndicator) return;
        const v1 = (inChangeNew.value || '').trim();
        const v2 = (inChangeConfirm.value || '').trim();
        const errEl = document.getElementById('change-password-error');

        if (!v1 && !v2) {
            changeMatchIndicator.classList.add('hidden');
            changeMatchIndicator.innerHTML = '';
            return;
        }

        changeMatchIndicator.classList.remove('hidden');

        if (v1.length < 8) {
            changeMatchIndicator.innerHTML = `<span class="inline-flex items-center gap-1.5 text-amber-600 bg-amber-50 px-2.5 py-1 rounded-md border border-amber-200"><i class="fa-solid fa-triangle-exclamation"></i> Mínimo 8 caracteres (llevas ${v1.length})</span>`;
            return;
        }

        if (v2.length === 0) {
            changeMatchIndicator.innerHTML = `<span class="inline-flex items-center gap-1.5 text-slate-500 bg-slate-50 px-2.5 py-1 rounded-md border border-slate-200"><i class="fa-solid fa-info-circle"></i> Escribe la misma clave abajo para confirmar</span>`;
            return;
        }

        if (v1 === v2) {
            changeMatchIndicator.innerHTML = `<span class="inline-flex items-center gap-1.5 text-emerald-700 bg-emerald-50 px-2.5 py-1 rounded-md border border-emerald-300 font-bold"><i class="fa-solid fa-circle-check text-emerald-600"></i> ¡Las contraseñas coinciden correctamente!</span>`;
            if (errEl) errEl.classList.add('hidden');
        } else {
            changeMatchIndicator.innerHTML = `<span class="inline-flex items-center gap-1.5 text-red-600 bg-red-50 px-2.5 py-1 rounded-md border border-red-200 font-bold"><i class="fa-solid fa-circle-xmark text-red-500"></i> Las contraseñas no coinciden</span>`;
        }
    }

    if (inChangeNew && inChangeConfirm) {
        inChangeNew.addEventListener('input', checkChangeMatchLive);
        inChangeConfirm.addEventListener('input', checkChangeMatchLive);
    }

    const changePwForm = document.getElementById('change-password-form');
    if (changePwForm) {
        changePwForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const newPw = (document.getElementById('change-new-password')?.value || '').trim();
            const confirmPw = (document.getElementById('change-confirm-password')?.value || '').trim();
            const errBox = document.getElementById('change-password-error');
            const errText = document.getElementById('change-password-error-text');
            const btnSubmit = document.getElementById('btn-change-password-submit');

            if (newPw.length < 8) {
                if (errBox && errText) {
                    errText.textContent = 'La nueva contraseña debe tener al menos 8 caracteres.';
                    errBox.classList.remove('hidden');
                }
                return;
            }

            if (newPw !== confirmPw) {
                if (errBox && errText) {
                    errText.textContent = 'Las contraseñas ingresadas no coinciden.';
                    errBox.classList.remove('hidden');
                }
                return;
            }

            if (errBox) errBox.classList.add('hidden');
            if (btnSubmit) {
                btnSubmit.disabled = true;
                btnSubmit.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1.5"></i>Actualizando...';
            }

            try {
                const targetU = getLoggedUser()?.username;
                await window.DIATDataService.updateUserPassword(newPw, targetU);

                const currentLog = getLoggedUser();
                if (currentLog) {
                    currentLog.passwordCustomized = true;
                    if (sessionStorage.getItem('diat_logged_user')) sessionStorage.setItem('diat_logged_user', JSON.stringify(currentLog));
                    if (localStorage.getItem('diat_logged_user')) localStorage.setItem('diat_logged_user', JSON.stringify(currentLog));
                }

                document.getElementById('modal-change-password').classList.add('hidden');
                checkAuthStatus();
                alertToast('Contraseña Actualizada', 'Tu contraseña ha sido actualizada exitosamente.');
            } catch (err) {
                console.error('[DIAT] Error en cambio voluntario de clave:', err);
                if (errBox && errText) {
                    errText.textContent = err.message || 'Error al actualizar contraseña.';
                    errBox.classList.remove('hidden');
                }
            } finally {
                if (btnSubmit) {
                    btnSubmit.disabled = false;
                    btnSubmit.innerHTML = 'Actualizar Contraseña';
                }
            }
        });
    }

    const triggerAuth = document.getElementById('btn-portal-login-trigger');
    if (triggerAuth) {
        triggerAuth.addEventListener('click', (e) => {
            if (typeof window.openLoginModal === 'function') {
                window.openLoginModal(e);
            } else {
                document.getElementById('modal-login')?.classList.remove('hidden');
            }
        });
    }

    // Formulario de Autorización de Administrador (Control de Visitas)
    const adminAuthForm = document.getElementById('admin-auth-form');
    if (adminAuthForm) {
        adminAuthForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const u = (document.getElementById('admin-auth-user')?.value || '').trim();
            const p = (document.getElementById('admin-auth-password')?.value || '').trim();
            const errBox = document.getElementById('admin-auth-error');
            const errText = document.getElementById('admin-auth-error-text');

            if (errBox) errBox.classList.add('hidden');
            if (!u || !p) {
                if (errBox && errText) {
                    errText.textContent = 'Por favor ingresa usuario y contraseña de Administrador.';
                    errBox.classList.remove('hidden');
                }
                return;
            }

            try {
                const authRes = await window.DIATDataService.loginUser(u, p);
                const isAuthAdmin = authRes.success && authRes.user && (
                    authRes.user.username === 'ADMIN' ||
                    (authRes.user.role && authRes.user.role.toLowerCase().includes('administrador'))
                );

                if (isAuthAdmin) {
                    window.diatAdminAuthorized = true;
                    sessionStorage.setItem('diat_admin_authorized', 'true');
                    const modal = document.getElementById('modal-admin-auth');
                    if (modal) modal.classList.add('hidden');
                    alertToast('Acceso Autorizado', 'Bienvenido al Control de Visitas (ADMIN).');

                    const cb = window.pendingAdminAuthCallback;
                    window.pendingAdminAuthCallback = null;
                    window.pendingAdminCancelCallback = null;
                    if (typeof cb === 'function') {
                        cb();
                    } else {
                        window.openControlVisitasHub('registrar');
                    }
                    return;
                }
            } catch (ex) {
                console.error('Error validando administrador:', ex);
            }

            if (errBox && errText) {
                errText.textContent = 'Credenciales de Administrador incorrectas o usuario no autorizado.';
                errBox.classList.remove('hidden');
            }
        });
    }

    const btnCloseAdminAuth = document.getElementById('btn-close-admin-auth');
    const btnCancelAdminAuth = document.getElementById('btn-cancel-admin-auth');
    [btnCloseAdminAuth, btnCancelAdminAuth].forEach(btn => {
        if (btn) {
            btn.addEventListener('click', () => {
                if (typeof window.closeAdminAuthModal === 'function') {
                    window.closeAdminAuthModal();
                } else {
                    const m = document.getElementById('modal-admin-auth');
                    if (m) m.classList.add('hidden');
                }
            });
        }
    });

    // 2. Enlace de Perfil en Header
    const headerProfile = document.getElementById('header-user-profile');
    if (headerProfile) {
        headerProfile.addEventListener('click', (e) => {
            e.stopPropagation();
            const logged = getLoggedUser();
            if (logged) {
                document.getElementById('user-menu-dropdown').classList.toggle('hidden');
            } else {
                if (typeof window.openLoginModal === 'function') {
                    window.openLoginModal(e);
                } else {
                    document.getElementById('modal-login')?.classList.remove('hidden');
                }
            }
        });
    }

    // Cerrar menú de usuario al hacer clic fuera
    document.addEventListener('click', () => {
        const dd = document.getElementById('user-menu-dropdown');
        if (dd) dd.classList.add('hidden');
    });

    // 3. Acciones de items del Menú de Usuario
    document.querySelectorAll('.user-menu-item').forEach(item => {
        item.addEventListener('click', (e) => {
            e.stopPropagation();
            document.getElementById('user-menu-dropdown').classList.add('hidden');
            const action = item.getAttribute('data-action');
            if (action === 'logout') {
                handleLogout();
            } else if (action === 'cambiar-password') {
                const modalChange = document.getElementById('modal-change-password');
                if (modalChange) {
                    modalChange.classList.remove('hidden');
                    const errBox = document.getElementById('change-password-error');
                    if (errBox) errBox.classList.add('hidden');
                    const indEl = document.getElementById('change-password-match-indicator');
                    if (indEl) { indEl.classList.add('hidden'); indEl.innerHTML = ''; }
                    const in1 = document.getElementById('change-new-password');
                    const in2 = document.getElementById('change-confirm-password');
                    if (in1) in1.value = '';
                    if (in2) in2.value = '';
                }
            } else if (action === 'visitas') {
                const vtTabBtn = document.querySelector('.tab-btn[data-tab="visitas"]');
                if (vtTabBtn) vtTabBtn.click();
            } else {
                // Ir a pestaña del portal
                const portalTabBtn = document.querySelector('.tab-btn[data-tab="portal"]');
                if (portalTabBtn) portalTabBtn.click();

                // Cambiar a la sub-pestaña correcta
                const targetSub = action === 'perfil' ? 'dashboard' : action;
                const subtabBtn = document.querySelector(`.portal-subtab-btn[data-subtab="${targetSub}"]`);
                if (subtabBtn) subtabBtn.click();
            }
        });
    });

    // Cerrar sesión desde botón interno del Portal
    const btnLogout = document.getElementById('btn-portal-logout');
    if (btnLogout) {
        btnLogout.addEventListener('click', handleLogout);
    }

    // 4. Navegación de sub-pestañas internas del Portal
    const subtabBtns = document.querySelectorAll('.portal-subtab-btn');
    subtabBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            subtabBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');

            const target = btn.getAttribute('data-subtab');
            document.querySelectorAll('.portal-panel').forEach(p => p.classList.add('hidden'));
            const panel = document.getElementById(`portal-panel-${target}`);
            if (panel) panel.classList.remove('hidden');
            if (target === 'auditoria' && typeof window.renderAuditoriaTab === 'function') {
                window.renderAuditoriaTab();
            }
            if (target === 'supervisores' && typeof window.renderAdminSupervisoresPanel === 'function') {
                window.renderAdminSupervisoresPanel();
            }
        });
    });

    // Acciones de Header del Portal Rediseñado
    const btnHeaderVisita = document.getElementById('btn-header-nueva-visita-portal');
    if (btnHeaderVisita) {
        btnHeaderVisita.addEventListener('click', () => {
            const regBtn = document.getElementById('btn-registrar-visita-portal');
            if (regBtn) regBtn.click();
        });
    }

    const btnHeaderPw = document.getElementById('btn-header-cambiar-pw-portal');
    if (btnHeaderPw) {
        btnHeaderPw.addEventListener('click', () => {
            const perfilSubtab = document.querySelector('.portal-subtab-btn[data-subtab="perfil"]');
            if (perfilSubtab) {
                perfilSubtab.click();
                const inp = document.getElementById('portal-direct-new-pw');
                if (inp) {
                    inp.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    inp.focus();
                }
            } else {
                const modalChange = document.getElementById('modal-change-password');
                if (modalChange) modalChange.classList.remove('hidden');
            }
        });
    }

    // Toolbar de búsqueda y filtros para convenios del supervisor
    const portalSearchInp = document.getElementById('portal-convenios-search');
    if (portalSearchInp) {
        portalSearchInp.addEventListener('input', () => {
            if (typeof window.filterSupervisorConvenios === 'function') {
                window.filterSupervisorConvenios();
            }
        });
    }

    document.querySelectorAll('.portal-filter-chip').forEach(chip => {
        chip.addEventListener('click', () => {
            document.querySelectorAll('.portal-filter-chip').forEach(c => c.classList.remove('active'));
            chip.classList.add('active');
            if (typeof window.filterSupervisorConvenios === 'function') {
                window.filterSupervisorConvenios();
            }
        });
    });

    // Formulario de cambio directo de contraseña en Mi Perfil
    const inDirectNew = document.getElementById('portal-direct-new-pw');
    const inDirectConfirm = document.getElementById('portal-direct-confirm-pw');
    const directMatchInd = document.getElementById('portal-direct-match-indicator');

    function checkDirectMatchLive() {
        if (!inDirectNew || !inDirectConfirm || !directMatchInd) return;
        const v1 = (inDirectNew.value || '').trim();
        const v2 = (inDirectConfirm.value || '').trim();
        const errEl = document.getElementById('portal-direct-error');

        if (!v1 && !v2) {
            directMatchInd.classList.add('hidden');
            directMatchInd.innerHTML = '';
            return;
        }

        directMatchInd.classList.remove('hidden');

        if (v1.length < 8) {
            directMatchInd.innerHTML = `<span class="inline-flex items-center gap-1.5 text-amber-600 bg-amber-50 px-2.5 py-1 rounded-md border border-amber-200"><i class="fa-solid fa-triangle-exclamation"></i> Mínimo 8 caracteres (llevas ${v1.length})</span>`;
            return;
        }

        if (v2.length === 0) {
            directMatchInd.innerHTML = `<span class="inline-flex items-center gap-1.5 text-slate-500 bg-slate-50 px-2.5 py-1 rounded-md border border-slate-200"><i class="fa-solid fa-info-circle"></i> Escribe la confirmación abajo</span>`;
            return;
        }

        if (v1 === v2) {
            directMatchInd.innerHTML = `<span class="inline-flex items-center gap-1.5 text-emerald-700 bg-emerald-50 px-2.5 py-1 rounded-md border border-emerald-300 font-bold"><i class="fa-solid fa-circle-check text-emerald-600"></i> ¡Las contraseñas coinciden correctamente!</span>`;
            if (errEl) errEl.classList.add('hidden');
        } else {
            directMatchInd.innerHTML = `<span class="inline-flex items-center gap-1.5 text-red-600 bg-red-50 px-2.5 py-1 rounded-md border border-red-200 font-bold"><i class="fa-solid fa-circle-xmark text-red-500"></i> Las contraseñas no coinciden</span>`;
        }
    }

    if (inDirectNew && inDirectConfirm) {
        inDirectNew.addEventListener('input', checkDirectMatchLive);
        inDirectConfirm.addEventListener('input', checkDirectMatchLive);
    }

    const directPwForm = document.getElementById('portal-direct-password-form');
    if (directPwForm) {
        directPwForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const newPw = (document.getElementById('portal-direct-new-pw')?.value || '').trim();
            const confirmPw = (document.getElementById('portal-direct-confirm-pw')?.value || '').trim();
            const errBox = document.getElementById('portal-direct-error');
            const errText = document.getElementById('portal-direct-error-text');
            const btnSubmit = document.getElementById('btn-portal-direct-pw-submit');

            if (newPw.length < 8) {
                if (errBox && errText) {
                    errText.textContent = 'La nueva contraseña debe tener al menos 8 caracteres.';
                    errBox.classList.remove('hidden');
                }
                return;
            }

            if (newPw !== confirmPw) {
                if (errBox && errText) {
                    errText.textContent = 'Las contraseñas ingresadas no coinciden.';
                    errBox.classList.remove('hidden');
                }
                return;
            }

            if (errBox) errBox.classList.add('hidden');
            if (btnSubmit) {
                btnSubmit.disabled = true;
                btnSubmit.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1.5"></i>Guardando...';
            }

            try {
                const targetU = getLoggedUser()?.username;
                await window.DIATDataService.updateUserPassword(newPw, targetU);

                const currentLog = getLoggedUser();
                if (currentLog) {
                    currentLog.passwordCustomized = true;
                    if (sessionStorage.getItem('diat_logged_user')) sessionStorage.setItem('diat_logged_user', JSON.stringify(currentLog));
                    if (localStorage.getItem('diat_logged_user')) localStorage.setItem('diat_logged_user', JSON.stringify(currentLog));
                }

                if (inDirectNew) inDirectNew.value = '';
                if (inDirectConfirm) inDirectConfirm.value = '';
                if (directMatchInd) {
                    directMatchInd.classList.add('hidden');
                    directMatchInd.innerHTML = '';
                }

                checkAuthStatus();
                alertToast('¡Contraseña Actualizada!', 'Tu nueva contraseña ha sido guardada exitosamente.');
            } catch (err) {
                console.error('[DIAT] Error en cambio directo de clave:', err);
                if (errBox && errText) {
                    errText.textContent = err.message || 'Error al actualizar contraseña.';
                    errBox.classList.remove('hidden');
                }
            } finally {
                if (btnSubmit) {
                    btnSubmit.disabled = false;
                    btnSubmit.innerHTML = '<i class="fa-solid fa-key"></i> Actualizar Contraseña Ahora';
                }
            }
        });
    }

    // 5. Navegación de pestañas del Modal de Edición
    const editTabBtns = document.querySelectorAll('.edit-tab-btn');
    editTabBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            editTabBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');

            const target = btn.getAttribute('data-edittab');
            document.querySelectorAll('.edit-panel').forEach(p => p.classList.add('hidden'));
            const panel = document.getElementById(`edit-panel-${target}`);
            if (panel) panel.classList.remove('hidden');

            if (target === 'ubicacion' && window.editMapInstance) {
                setTimeout(() => {
                    window.editMapInstance.invalidateSize();
                }, 100);
            }
        });
    });

    // 6. Enlace de carga de fotos generales
    const fotoInput = document.getElementById('edit-foto-input');
    if (fotoInput) {
        fotoInput.addEventListener('change', async (e) => {
            const files = Array.from(e.target.files);
            if (files.length === 0) return;

            let loaded = 0;
            for (const file of files) {
                try {
                    const compressedBase64 = await compressImage(file);
                    window.editUploadedPhotos.push({
                        name: file.name,
                        base64: compressedBase64
                    });
                } catch (err) {
                    console.error("Error comprimiendo imagen general:", err);
                }
                loaded++;
                if (loaded === files.length) {
                    renderPhotoPreviews();
                    e.target.value = ''; // limpiar input
                }
            }
        });
    }

    // Enlace de carga de fotos para visitas técnicas
    window.visitUploadedPhotos = [];
    const visitFotoInput = document.getElementById('visit-foto-input');
    if (visitFotoInput) {
        visitFotoInput.addEventListener('change', async (e) => {
            const files = Array.from(e.target.files);
            if (files.length === 0) return;

            let loaded = 0;
            for (const file of files) {
                try {
                    const compressedBase64 = await compressImage(file);
                    window.visitUploadedPhotos.push(compressedBase64);
                } catch (err) {
                    console.error("Error comprimiendo imagen de visita:", err);
                }
                loaded++;
                if (loaded === files.length) {
                    renderVisitPhotoPreviews();
                    e.target.value = ''; // limpiar input
                }
            }
        });
    }

    // 7. Geolocalización celular para visitas
    const btnGPS = document.getElementById('btn-visit-capture-gps');
    if (btnGPS) {
        btnGPS.addEventListener('click', () => {
            if (navigator.geolocation) {
                navigator.geolocation.getCurrentPosition(
                    (position) => {
                        const lat = position.coords.latitude;
                        const lng = position.coords.longitude;
                        document.getElementById('visit-gps-lat').value = lat.toFixed(6);
                        document.getElementById('visit-gps-lng').value = lng.toFixed(6);

                        if (window.visitMapInstance && window.visitMarker) {
                            const pos = L.latLng(lat, lng);
                            window.visitMarker.setLatLng(pos);
                            window.visitMapInstance.setView(pos, 15);
                        }
                        alertToast("Ubicación capturada con éxito", "success");
                    },
                    (err) => {
                        console.warn("Error de geolocalización, usando mock:", err);
                        // Mock de coordenadas en Antioquia (Medellín/Jericó)
                        const lat = 6.25184 + (Math.random() - 0.5) * 0.05;
                        const lng = -75.56359 + (Math.random() - 0.5) * 0.05;
                        document.getElementById('visit-gps-lat').value = lat.toFixed(6);
                        document.getElementById('visit-gps-lng').value = lng.toFixed(6);
                        if (window.visitMapInstance && window.visitMarker) {
                            const pos = L.latLng(lat, lng);
                            window.visitMarker.setLatLng(pos);
                            window.visitMapInstance.setView(pos, 15);
                        }
                        alertToast("GPS no disponible. Se generaron coordenadas de simulación.", "warning");
                    }
                );
            } else {
                alertToast("Geolocalización no soportada por el navegador", "error");
            }
        });
    }

    // Actualizar marcador al cambiar manualmente lat/lng inputs de visita
    ['visit-gps-lat', 'visit-gps-lng'].forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('change', () => {
                const lat = parseFloat(document.getElementById('visit-gps-lat').value);
                const lng = parseFloat(document.getElementById('visit-gps-lng').value);
                if (!isNaN(lat) && !isNaN(lng) && window.visitMapInstance && window.visitMarker) {
                    const pos = L.latLng(lat, lng);
                    window.visitMarker.setLatLng(pos);
                    window.visitMapInstance.setView(pos, 14);
                }
            });
        }
    });

    // Función para inicializar mapa de visita
    window.visitMapInstance = null;
    window.visitMarker = null;
    function initVisitMap(lat, lng) {
        const mapDiv = document.getElementById('visit-map');
        if (!mapDiv) return;

        const initialPos = (lat && lng && lat !== 0 && lng !== 0) ? L.latLng(lat, lng) : L.latLng(6.25184, -75.56359);
        const initialZoom = (lat && lng && lat !== 0 && lng !== 0) ? 14 : 8;

        if (!window.visitMapInstance) {
            window.visitMapInstance = L.map('visit-map', {
                zoomControl: true,
                attributionControl: false
            });

            L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', {
                maxZoom: 19,
                attribution: 'Esri',
                crossOrigin: true
            }).addTo(window.visitMapInstance);

            window.visitMarker = L.marker(initialPos, {
                draggable: true
            }).addTo(window.visitMapInstance);

            window.visitMarker.on('dragend', function () {
                const pos = window.visitMarker.getLatLng();
                document.getElementById('visit-gps-lat').value = pos.lat.toFixed(6);
                document.getElementById('visit-gps-lng').value = pos.lng.toFixed(6);
            });

            window.visitMapInstance.on('click', function (e) {
                window.visitMarker.setLatLng(e.latlng);
                document.getElementById('visit-gps-lat').value = e.latlng.lat.toFixed(6);
                document.getElementById('visit-gps-lng').value = e.latlng.lng.toFixed(6);
            });
        } else {
            window.visitMarker.setLatLng(initialPos);
        }

        window.visitMapInstance.setView(initialPos, initialZoom);
        setTimeout(() => {
            window.visitMapInstance.invalidateSize();
        }, 100);
    }
    window.initVisitMap = initVisitMap;

    // Función para inicializar mapa de detalle de visita (solo lectura)
    window.visitDetailMapInstance = null;
    window.visitDetailMarker = null;
    function initVisitDetailMap(lat, lng) {
        const mapDiv = document.getElementById('visit-detail-map');
        if (!mapDiv) return;

        const initialPos = (lat && lng && lat !== 0 && lng !== 0) ? L.latLng(lat, lng) : L.latLng(6.25184, -75.56359);
        const initialZoom = (lat && lng && lat !== 0 && lng !== 0) ? 14 : 8;

        if (!window.visitDetailMapInstance) {
            window.visitDetailMapInstance = L.map('visit-detail-map', {
                zoomControl: true,
                attributionControl: false
            });

            L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', {
                maxZoom: 19,
                attribution: 'Esri',
                crossOrigin: true
            }).addTo(window.visitDetailMapInstance);

            window.visitDetailMarker = L.marker(initialPos).addTo(window.visitDetailMapInstance);
        } else {
            window.visitDetailMarker.setLatLng(initialPos);
        }

        window.visitDetailMapInstance.setView(initialPos, initialZoom);
        setTimeout(() => {
            window.visitDetailMapInstance.invalidateSize();
        }, 100);
    }
    window.initVisitDetailMap = initVisitDetailMap;

    // Modal para visualizar detalle de visita técnica
    window.openVisitDetailModal = function (visitId) {
        const visits = window.DIATDataService.getTechnicalVisits();
        const v = visits.find(visit => visit.id === visitId);
        if (!v) return;

        const clean = (typeof cleanMojibake === 'function') ? cleanMojibake : (str => str || '');
        const estadoLabel = (v.estado === 'Programada' ? 'PROGRAMADA' : 'REALIZADA');
        document.getElementById('visit-detail-title').textContent = `Visita Técnica (${estadoLabel}) - Convenio N° ${clean(v.convenioId)}`;
        document.getElementById('visit-detail-subtitle').textContent = `${v.estado === 'Programada' ? 'Fecha Estimada' : 'Fecha de Visita'}: ${v.fecha}`;
        document.getElementById('visit-detail-tipo').textContent = clean(v.tipo);
        document.getElementById('visit-detail-usuario').textContent = clean(v.usuario) || 'N/A';
        document.getElementById('visit-detail-obs').textContent = clean(v.observaciones) || (v.estado === 'Programada' ? 'Visita técnica programada. Las observaciones se registrarán una vez realizada.' : '--');
        document.getElementById('visit-detail-compromisos').textContent = clean(v.compromisos) || (v.estado === 'Programada' ? 'Compromisos a definir en terreno.' : '--');
        document.getElementById('visit-detail-riesgos').textContent = clean(v.riesgos) || '--';

        // Mostrar botón de editar si el usuario logueado es el creador de la visita
        const loggedUser = getLoggedUser();
        const btnEdit = document.getElementById('btn-edit-visit-detail');
        if (btnEdit) {
            if (loggedUser && v.usuario && loggedUser.name.trim().toUpperCase() === v.usuario.trim().toUpperCase()) {
                btnEdit.classList.remove('hidden');
                btnEdit.dataset.visitId = v.id;
            } else {
                btnEdit.classList.add('hidden');
                delete btnEdit.dataset.visitId;
            }
        }

        // Cargar fotos
        const photosContainer = document.getElementById('visit-detail-photos');
        const emptyPhotos = document.getElementById('visit-detail-photos-empty');
        photosContainer.innerHTML = '';

        if (v.photos && v.photos.length > 0) {
            emptyPhotos.classList.add('hidden');
            photosContainer.classList.remove('hidden');
            v.photos.forEach((photo, idx) => {
                const img = document.createElement('img');
                img.src = photo;
                img.className = 'w-full aspect-square object-cover rounded border border-slate-200 cursor-pointer hover:opacity-90 transition-all';
                img.addEventListener('click', (e) => {
                    e.stopPropagation();
                    window.openVisitPhotoLightbox(v.id, idx);
                });
                photosContainer.appendChild(img);
            });
        } else {
            emptyPhotos.classList.remove('hidden');
            emptyPhotos.textContent = (v.estado === 'Programada' ? 'Sin registro fotográfico (visita programada para ejecución futura)' : 'No se adjuntaron fotos en esta visita.');
            photosContainer.classList.add('hidden');
        }

        // Cargar ubicación
        const lat = parseFloat(v.lat) || 0;
        const lng = parseFloat(v.lng) || 0;
        document.getElementById('visit-detail-lat').textContent = lat !== 0 ? lat.toFixed(6) : 'N/A';
        document.getElementById('visit-detail-lng').textContent = lng !== 0 ? lng.toFixed(6) : 'N/A';

        // Mostrar modal
        document.getElementById('modal-detalle-visita').style.display = 'flex';
        document.getElementById('modal-detalle-visita').classList.remove('hidden');

        // Inicializar mapa de detalle
        setTimeout(() => {
            initVisitDetailMap(lat, lng);
        }, 200);
    };

    // Cerrar modal de detalle de visitas
    ['btn-close-visit-detail-modal', 'btn-close-visit-detail'].forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('click', () => {
                document.getElementById('modal-detalle-visita').style.display = 'none';
                document.getElementById('modal-detalle-visita').classList.add('hidden');
            });
        }
    });

    window.editingVisitId = null;

    window.openEditVisitModal = function (visitId) {
        checkOrPromptAuthPassword('editar esta visita técnica', () => {
            window.openControlVisitasHub('editar_especifica', visitId);
        });
    };

    const btnEditVisitDetail = document.getElementById('btn-edit-visit-detail');
    if (btnEditVisitDetail) {
        btnEditVisitDetail.addEventListener('click', () => {
            const visitId = btnEditVisitDetail.dataset.visitId;
            if (visitId) {
                checkOrPromptAuthPassword('editar esta visita técnica', () => {
                    document.getElementById('modal-detalle-visita').style.display = 'none';
                    document.getElementById('modal-detalle-visita').classList.add('hidden');
                    window.openControlVisitasHub('editar_especifica', visitId);
                });
            }
        });
    }

    // 8. Guardar Visita en el nuevo modal independiente
    const btnSaveVisit = document.getElementById('btn-save-visit');
    if (btnSaveVisit) {
        btnSaveVisit.addEventListener('click', async () => {
            const convenioId = document.getElementById('visit-convenio-select').value;
            if (!convenioId) {
                alertToast("Error", "Debes seleccionar un convenio para registrar la visita", "error");
                return;
            }

            const fechaVal = document.getElementById('visit-fecha').value;
            const tipo = document.getElementById('visit-tipo').value;
            const estado = document.getElementById('visit-estado') ? document.getElementById('visit-estado').value : 'Realizada';
            const prioridad = document.getElementById('visit-prioridad') ? document.getElementById('visit-prioridad').value : 'Media';
            const supervisorInput = document.getElementById('visit-supervisor-input') ? document.getElementById('visit-supervisor-input').value.trim() : '';
            let observaciones = document.getElementById('visit-obs').value;
            const compromisos = document.getElementById('visit-compromisos').value;
            const riesgos = document.getElementById('visit-riesgos').value;
            const lat = parseFloat(document.getElementById('visit-gps-lat').value) || 0;
            const lng = parseFloat(document.getElementById('visit-gps-lng').value) || 0;

            if (estado === 'Realizada' && !observaciones.trim()) {
                alertToast("Error", "Las observaciones técnicas son obligatorias para registrar una visita realizada", "error");
                return;
            }

            if (estado === 'Programada' && !observaciones.trim()) {
                observaciones = 'Visita técnica programada para inspección en terreno.';
            }

            const user = getLoggedUser();
            const username = supervisorInput || (user ? user.name : 'Jonathan Marín Gallego');
            const supervisorList = supervisorInput ? supervisorInput.split(/[,;\/]+/).map(s => s.trim()).filter(Boolean) : [username];

            // Buscar datos del convenio y municipio para enriquecer la visita
            const convRow = (rawData || []).find(r => String(r['CONVENIO']).trim() === String(convenioId).trim()) || {};
            const muniSelect = document.getElementById('visit-municipio-select');
            const selectedMuni = muniSelect ? muniSelect.value.trim() : '';
            const municipio = selectedMuni || convRow['MUNICIPIO'] || '';
            const subregion = convRow['SUBREGION'] || (typeof getSubregionForMuni === 'function' ? getSubregionForMuni(municipio) : '');

            btnSaveVisit.disabled = true;
            const oldHtml = btnSaveVisit.innerHTML;

            const isEdit = !!window.editingVisitId;
            if (isEdit) {
                btnSaveVisit.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1"></i>Guardando...';
                await window.DIATDataService.updateTechnicalVisit(window.editingVisitId, {
                    fecha: fechaVal ? toDateInputValue(fechaVal) : undefined,
                    tipo,
                    estado,
                    prioridad,
                    usuario: username,
                    supervisores: supervisorList,
                    municipio: municipio || undefined,
                    subregion: subregion || undefined,
                    observaciones,
                    compromisos,
                    riesgos,
                    lat,
                    lng,
                    photos: window.visitUploadedPhotos
                });
            } else {
                btnSaveVisit.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1"></i>Registrando...';
                // Guardar visita técnica
                await window.DIATDataService.addTechnicalVisit(username, convenioId, {
                    fecha: fechaVal ? toDateInputValue(fechaVal) : undefined,
                    tipo,
                    estado,
                    prioridad,
                    municipio,
                    subregion,
                    observaciones,
                    compromisos,
                    riesgos,
                    lat,
                    lng,
                    supervisores: supervisorList,
                    photoCount: (estado === 'Programada' ? 0 : window.visitUploadedPhotos.length),
                    photos: (estado === 'Programada' ? [] : window.visitUploadedPhotos)
                });
            }

            // Si las coordenadas son válidas, actualizar la ubicación del convenio en la base de datos
            if (lat !== 0 && lng !== 0) {
                const row = rawData.find(r => String(r['CONVENIO']).trim() === String(convenioId).trim());
                if (row) {
                    await window.DIATDataService.saveConvenioUpdate(username, convenioId, {
                        'LATITUD': lat,
                        'LONGITUD': lng
                    }, row);
                }
            }

            btnSaveVisit.disabled = false;
            btnSaveVisit.innerHTML = oldHtml;

            // Limpiar campos y cerrar modal
            document.getElementById('visit-obs').value = '';
            document.getElementById('visit-compromisos').value = '';
            document.getElementById('visit-riesgos').value = '';
            window.visitUploadedPhotos = [];
            if (document.getElementById('visit-foto-input')) document.getElementById('visit-foto-input').value = '';
            renderVisitPhotoPreviews();

            // Restaurar estado del selector de convenios
            const selectEl = document.getElementById('visit-convenio-select');
            if (selectEl) selectEl.disabled = false;

            document.getElementById('modal-registrar-visita').style.display = 'none';
            document.getElementById('modal-registrar-visita').classList.add('hidden');

            if (isEdit) {
                alertToast('Visita Actualizada', 'La visita técnica ha sido modificada con éxito.');
            } else {
                alertToast('Visita Registrada', 'La visita técnica ha sido guardada con éxito.');
            }
            window.editingVisitId = null;
            const hubBanner = document.getElementById('hub-editing-banner');
            if (hubBanner) {
                hubBanner.classList.add('hidden');
                hubBanner.classList.remove('flex');
            }
            if (typeof renderHubVisitsList === 'function') renderHubVisitsList();

            // Recargar datos y fusionar
            if (window.baseExcelData && window.DIATDataService) {
                rawData = window.DIATDataService.mergeData(window.baseExcelData);
            }

            // Actualizar dashboard principal, mapa, listados, portal y pestaña de visitas
            applyFilters();
            if (typeof renderSupervisorPortal === 'function') renderSupervisorPortal();
            if (typeof renderVisitasTab === 'function') renderVisitasTab();
        });
    }

    // Al cambiar la selección en el selector de convenios del modal de visitas
    const visitConvenioSelect = document.getElementById('visit-convenio-select');
    if (visitConvenioSelect) {
        visitConvenioSelect.addEventListener('change', () => {
            const convenioId = visitConvenioSelect.value;
            const row = rawData.find(r => String(r['CONVENIO']).trim() === String(convenioId).trim());
            if (row) {
                const lat = parseFloat(row['LATITUD']) || 0;
                const lng = parseFloat(row['LONGITUD']) || 0;
                document.getElementById('visit-gps-lat').value = lat !== 0 ? lat.toFixed(6) : '';
                document.getElementById('visit-gps-lng').value = lng !== 0 ? lng.toFixed(6) : '';
                initVisitMap(lat, lng);
            }
        });
    }

    // 9. Registrar Visita desde pestaña del portal (Abre nuevo modal independiente)
    const btnRegistrarPortal = document.getElementById('btn-registrar-visita-portal');
    if (btnRegistrarPortal) {
        btnRegistrarPortal.addEventListener('click', () => {
            const currentUser = getLoggedUser();
            if (window.DIATDataService && !window.DIATDataService.hasPermission(currentUser, 'canCreateVisits')) {
                alertToast('Acceso Denegado', 'No tienes permisos asignados para registrar visitas en terreno.', 'warning');
                return;
            }

            const supervisorRows = getSupervisorRows();
            if (supervisorRows.length === 0) {
                alertToast('Sin convenios', 'No tienes convenios asignados para registrar visitas.', 'warning');
                return;
            }

            window.editingVisitId = null;
            const titleEl = document.getElementById('modal-registrar-visita-title');
            const descEl = document.getElementById('modal-registrar-visita-desc');
            if (titleEl) titleEl.textContent = "Registrar Nueva Visita Técnica";
            if (descEl) descEl.textContent = "Ingreso de informe de supervisión y geolocalización";

            // Resetear inputs del formulario de visita
            document.getElementById('visit-fecha').value = toDateInputValue('');
            document.getElementById('visit-tipo').value = 'Avance de obra';
            document.getElementById('visit-obs').value = '';
            document.getElementById('visit-compromisos').value = '';
            document.getElementById('visit-riesgos').value = '';
            window.visitUploadedPhotos = [];
            if (document.getElementById('visit-foto-input')) document.getElementById('visit-foto-input').value = '';
            renderVisitPhotoPreviews();

            // Poblar dropdown select
            const selectEl = document.getElementById('visit-convenio-select');
            if (selectEl) {
                selectEl.disabled = false;
                selectEl.innerHTML = '';
                supervisorRows.forEach((r, idx) => {
                    const opt = document.createElement('option');
                    opt.value = String(r['CONVENIO']).trim();
                    opt.textContent = `Convenio ${r['CONVENIO']} - ${r['MUNICIPIO'] || ''} (${r['ESTADO CONVENIO'] || ''})`;
                    selectEl.appendChild(opt);
                });
            }

            // Seleccionar el primero por defecto y cargar ubicación
            const firstRow = supervisorRows[0];
            const lat = parseFloat(firstRow['LATITUD']) || 0;
            const lng = parseFloat(firstRow['LONGITUD']) || 0;
            document.getElementById('visit-gps-lat').value = lat !== 0 ? lat.toFixed(6) : '';
            document.getElementById('visit-gps-lng').value = lng !== 0 ? lng.toFixed(6) : '';

            // Mostrar modal
            document.getElementById('modal-registrar-visita').style.display = 'flex';
            document.getElementById('modal-registrar-visita').classList.remove('hidden');

            // Inicializar mapa
            setTimeout(() => {
                initVisitMap(lat, lng);
            }, 200);
        });
    }

    // 10. Botones de cerrar modal de actualización de convenios
    ['btn-close-edit-modal', 'btn-cancel-edit'].forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('click', () => {
                document.getElementById('modal-actualizar-convenio').style.display = 'none';
                document.getElementById('modal-actualizar-convenio').classList.add('hidden');
            });
        }
    });

    // Cerrar modal de registro de visitas
    ['btn-close-visit-modal', 'btn-cancel-visit'].forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.addEventListener('click', () => {
                document.getElementById('modal-registrar-visita').style.display = 'none';
                document.getElementById('modal-registrar-visita').classList.add('hidden');
            });
        }
    });

    // 11. Botón guardar cambios de convenio
    const btnSaveEdit = document.getElementById('btn-save-edit');
    if (btnSaveEdit) {
        btnSaveEdit.addEventListener('click', async () => {
            const convenioId = document.getElementById('edit-general-id').value;
            const row = rawData.find(r => String(r['CONVENIO']).trim() === String(convenioId).trim());
            if (!row) return;

            const currentUser = getLoggedUser();
            if (window.DIATDataService && !window.DIATDataService.hasPermission(currentUser, 'canEditConvenios')) {
                alertToast("Acceso Denegado", "No tienes permisos asignados para editar convenios. Consulta con el Administrador DIAT.", "error");
                return;
            }

            const estado = document.getElementById('edit-general-estado').value;
            const fisico = parseFloat(document.getElementById('edit-seg-fisico').value) || 0;
            const financiero = parseFloat(document.getElementById('edit-seg-financiero').value) || 0;
            const longitud = parseFloat(document.getElementById('edit-seg-longitud').value) || 0;
            const area = parseFloat(document.getElementById('edit-seg-area').value) || 0;
            const desembolsado = parseFloat(document.getElementById('edit-seg-desembolsado').value) || 0;
            const autorizado = parseFloat(document.getElementById('edit-seg-autorizado').value) || 0;
            const corteInput = document.getElementById('edit-seg-corte').value;
            const observaciones = document.getElementById('edit-seg-obs').value;

            if (isNaN(fisico) || fisico < 0) {
                alertToast("Avance Inválido", "El avance físico debe ser mayor o igual a 0", "error");
                return;
            }
            if (isNaN(financiero) || financiero < 0) {
                alertToast("Avance Inválido", "El avance financiero debe ser mayor o igual a 0", "error");
                return;
            }

            // Convertir fecha de corte a DD/MM/YYYY
            let fechaCorte = '';
            if (corteInput) {
                const parts = corteInput.split('-');
                if (parts.length === 3) {
                    fechaCorte = `${parts[2]}/${parts[1]}/${parts[0]}`;
                }
            }

            const isAnterior = isCuatrenioAnterior(row);
            const updatedFields = {
                'ESTADO CONVENIO': estado,
                'VALOR TOTAL DESEMBOLSADO': desembolsado,
                'VALOR TOTAL AUTORIZADO DEPARTAMENTO': autorizado,
                'OBSERVACIONES': observaciones
            };

            const l24 = parseFloat(document.getElementById('edit-seg-long-2024')?.value) || 0;
            const l25 = parseFloat(document.getElementById('edit-seg-long-2025')?.value) || 0;
            const l26 = parseFloat(document.getElementById('edit-seg-long-2026')?.value) || 0;
            const l27 = parseFloat(document.getElementById('edit-seg-long-2027')?.value) || 0;

            const a24 = parseFloat(document.getElementById('edit-seg-area-2024')?.value) || 0;
            const a25 = parseFloat(document.getElementById('edit-seg-area-2025')?.value) || 0;
            const a26 = parseFloat(document.getElementById('edit-seg-area-2026')?.value) || 0;
            const a27 = parseFloat(document.getElementById('edit-seg-area-2027')?.value) || 0;

            // Guardar discriminación anual en updatedFields para sincronizar con Google Sheets y DIATDataService
            updatedFields['LONGITUD EJECUTADA 2024(m)'] = l24;
            updatedFields['LONGITUD EJECUTADA 2025(m)'] = l25;
            updatedFields['LONGITUD EJECUTADA 2026(m)'] = l26;
            updatedFields['LONGITUD EJECUTADA 2027(m)'] = l27;

            updatedFields['AREA EJECUTADA 2024 (m2)'] = a24;
            updatedFields['AREA EJECUTADA 2025 (m2)'] = a25;
            updatedFields['AREA EJECUTADA 2026 (m2)'] = a26;
            updatedFields['AREA EJECUTADA 2027 (m2)'] = a27;

            // Actualizar objeto en memoria
            row['LONGITUD EJECUTADA 2024'] = l24;
            row['LONGITUD EJECUTADA 2025'] = l25;
            row['LONGITUD EJECUTADA 2026'] = l26;
            row['LONGITUD EJECUTADA 2027'] = l27;

            row['AREA EJECUTADA 2024'] = a24;
            row['AREA EJECUTADA 2025'] = a25;
            row['AREA EJECUTADA 2026'] = a26;
            row['AREA EJECUTADA 2027'] = a27;

            const sumLongYears = l24 + l25 + l26 + l27;
            const sumAreaYears = a24 + a25 + a26 + a27;

            const finalLongitud = sumLongYears > 0 ? sumLongYears : longitud;
            const finalArea = sumAreaYears > 0 ? sumAreaYears : area;

            if (isAnterior) {
                updatedFields['LONGITUD EJECUTADA CUATRENIO(m)'] = finalLongitud;
                updatedFields['AREA EJECUTADA CUATRENIO (m2)'] = finalArea;
                row['LONGITUD EJECUTADA CUATRENIO'] = finalLongitud;
                row['AREA EJECUTADA CUATRENIO (M2)'] = finalArea;
            } else {
                updatedFields['LONGITUD EJECUTADA CUATRENIO(m)'] = finalLongitud;
                updatedFields['LONGITUD EJECUTADA (m)'] = finalLongitud;
                updatedFields['AREA EJECUTADA CUATRENIO (m2)'] = finalArea;
                updatedFields['AREA EJECUTADA (m2)'] = finalArea;
                row['LONGITUD EJECUTADA CUATRENIO'] = finalLongitud;
                row['LONGITUD EJECUTADA'] = finalLongitud;
                row['AREA EJECUTADA CUATRENIO (M2)'] = finalArea;
                row['AREA EJECUTADA (M2)'] = finalArea;
            }

            const user = getLoggedUser();
            const username = user ? user.name : 'Jonathan Marín';

            // Mostrar la barra de progreso y ocultar botones para retroalimentación visual inmediata
            const progressContainer = document.getElementById('edit-save-progress-container');
            const progressText = document.getElementById('edit-save-progress-text');
            const progressPct = document.getElementById('edit-save-progress-pct');
            const progressBar = document.getElementById('edit-save-progress-bar');
            const actionsContainer = document.getElementById('edit-actions-container');

            if (progressContainer && actionsContainer) {
                progressContainer.classList.remove('hidden');
                actionsContainer.classList.add('hidden');
                progressBar.style.width = '20%';
                progressPct.textContent = '20%';
                progressText.textContent = 'Conectando con Google Sheets...';
            }

            // Guardar cambios en el service (Google Sheets de forma real)
            if (progressText && progressBar && progressPct) {
                progressBar.style.width = '40%';
                progressPct.textContent = '40%';
                progressText.textContent = 'Sincronizando con base en la nube...';
            }

            const saveSuccess = await window.DIATDataService.saveConvenioUpdate(username, convenioId, updatedFields, row);

            if (saveSuccess) {
                // Guardar fotos
                localStorage.setItem('diat_photos_' + convenioId, JSON.stringify(window.editUploadedPhotos));

                // Retraso de propagación para que Google Sheets procese los cambios en el XLSX de exportación
                const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

                if (progressText && progressBar && progressPct) {
                    progressBar.style.width = '60%';
                    progressPct.textContent = '60%';
                    progressText.textContent = 'Guardando cambios en Google Sheets...';
                }
                await delay(1000);

                if (progressText && progressBar && progressPct) {
                    progressBar.style.width = '75%';
                    progressPct.textContent = '75%';
                    progressText.textContent = 'Esperando procesamiento de la nube (2s)...';
                }
                await delay(1000);

                if (progressText && progressBar && progressPct) {
                    progressBar.style.width = '90%';
                    progressPct.textContent = '90%';
                    progressText.textContent = 'Esperando procesamiento de la nube (1s)...';
                }
                await delay(1000);

                if (progressText && progressBar && progressPct) {
                    progressBar.style.width = '95%';
                    progressPct.textContent = '95%';
                    progressText.textContent = 'Descargando base de datos actualizada...';
                }

                // Recargar datos directamente desde la nube (Google Sheets) para reflejar los cambios
                await loadExcelFile();

                if (progressText && progressBar && progressPct) {
                    progressBar.style.width = '100%';
                    progressPct.textContent = '100%';
                    progressText.textContent = '¡Sincronización exitosa!';
                }

                setTimeout(() => {
                    // Cerrar modal
                    document.getElementById('modal-actualizar-convenio').style.display = 'none';
                    document.getElementById('modal-actualizar-convenio').classList.add('hidden');

                    // Restaurar botones para la siguiente apertura
                    progressContainer.classList.add('hidden');
                    actionsContainer.classList.remove('hidden');

                    // Actualizar portal
                    renderSupervisorPortal();

                    alertToast("Sincronización Exitosa", "Convenio actualizado y sincronizado con Google Sheets.");
                }, 500);
            } else {
                // Restaurar botones si falla
                if (progressContainer && actionsContainer) {
                    progressContainer.classList.add('hidden');
                    actionsContainer.classList.remove('hidden');
                }
            }
        });
    }

    // Funciones de cálculo automático de avances físico y financiero
    const updateCalculatedFisico = () => {
        const alcanceM = parseFloat(document.getElementById('edit-alcance-m').value) || 0;
        const alcanceM2 = parseFloat(document.getElementById('edit-alcance-m2').value) || 0;
        const longitud = parseFloat(document.getElementById('edit-seg-longitud').value) || 0;
        const area = parseFloat(document.getElementById('edit-seg-area').value) || 0;

        let fisico = 0;
        if (alcanceM > 0) {
            fisico = (longitud / alcanceM) * 100;
        } else if (alcanceM2 > 0) {
            fisico = (area / alcanceM2) * 100;
        }
        document.getElementById('edit-seg-fisico').value = fisico.toFixed(1);
    };

    const updateCalculatedFinanciero = () => {
        const desembolsado = parseFloat(document.getElementById('edit-seg-desembolsado').value) || 0;
        const autorizado = parseFloat(document.getElementById('edit-seg-autorizado').value) || 0;

        let financiero = 0;
        if (desembolsado > 0) {
            financiero = (autorizado / desembolsado) * 100;
        }
        document.getElementById('edit-seg-financiero').value = financiero.toFixed(1);
    };

    // Auto-sumar campos anuales a longitud ejecutada cuatrienio
    const autoSumAnnualLongitud = () => {
        const l24 = parseFloat(document.getElementById('edit-seg-long-2024')?.value) || 0;
        const l25 = parseFloat(document.getElementById('edit-seg-long-2025')?.value) || 0;
        const l26 = parseFloat(document.getElementById('edit-seg-long-2026')?.value) || 0;
        const l27 = parseFloat(document.getElementById('edit-seg-long-2027')?.value) || 0;
        const sum = l24 + l25 + l26 + l27;
        const anyFilled = ['2024', '2025', '2026', '2027'].some(y => {
            const v = document.getElementById('edit-seg-long-' + y)?.value;
            return v !== undefined && v !== null && String(v).trim() !== '';
        });
        if (anyFilled) {
            document.getElementById('edit-seg-longitud').value = sum;
        }
        updateCalculatedFisico();
    };

    // Auto-sumar campos anuales a área ejecutada cuatrienio
    const autoSumAnnualArea = () => {
        const a24 = parseFloat(document.getElementById('edit-seg-area-2024')?.value) || 0;
        const a25 = parseFloat(document.getElementById('edit-seg-area-2025')?.value) || 0;
        const a26 = parseFloat(document.getElementById('edit-seg-area-2026')?.value) || 0;
        const a27 = parseFloat(document.getElementById('edit-seg-area-2027')?.value) || 0;
        const sum = a24 + a25 + a26 + a27;
        const anyFilled = ['2024', '2025', '2026', '2027'].some(y => {
            const v = document.getElementById('edit-seg-area-' + y)?.value;
            return v !== undefined && v !== null && String(v).trim() !== '';
        });
        if (anyFilled) {
            document.getElementById('edit-seg-area').value = sum;
        }
        updateCalculatedFisico();
    };

    // Registrar los escuchas para recalcular automáticamente
    ['edit-seg-longitud', 'edit-seg-area'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.addEventListener('input', updateCalculatedFisico);
    });

    ['edit-seg-long-2024', 'edit-seg-long-2025', 'edit-seg-long-2026', 'edit-seg-long-2027'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.addEventListener('input', autoSumAnnualLongitud);
    });

    ['edit-seg-area-2024', 'edit-seg-area-2025', 'edit-seg-area-2026', 'edit-seg-area-2027'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.addEventListener('input', autoSumAnnualArea);
    });

    ['edit-seg-desembolsado', 'edit-seg-autorizado'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.addEventListener('input', updateCalculatedFinanciero);
    });

    checkAuthStatus();
}

// Comprueba estado de sesión y dibuja perfil en Header y Portal
function checkAuthStatus() {
    const user = getLoggedUser();
    const btnLoginTrigger = document.getElementById('btn-login-trigger');
    const headerName = document.getElementById('header-user-name');
    const headerRole = document.getElementById('header-user-role');
    const headerAvatarImg = document.getElementById('header-user-avatar-img');

    // Elementos del dropdown
    const ddName = document.getElementById('dropdown-user-name');
    const ddRole = document.getElementById('dropdown-user-role');

    // Paneles del Portal
    const unauthorized = document.getElementById('portal-unauthorized');
    const authorized = document.getElementById('portal-authorized');

    if (user) {
        if (btnLoginTrigger) btnLoginTrigger.classList.add('hidden');
        if (headerName) headerName.textContent = user.name;
        if (headerRole) headerRole.textContent = user.role;
        if (headerAvatarImg) {
            headerAvatarImg.src = `https://ui-avatars.com/api/?name=${encodeURIComponent(user.name)}&background=0B5640&color=fff&bold=true`;
        }
        if (ddName) ddName.textContent = user.name;
        if (ddRole) ddRole.textContent = user.role;

        // Actualizar avatar y título de bienvenida del portal
        const portalAvatar = document.getElementById('portal-user-avatar');
        if (portalAvatar) portalAvatar.textContent = user.initials || 'SP';

        const portalWelcome = document.getElementById('portal-welcome-title');
        if (portalWelcome) portalWelcome.textContent = `Bienvenido, ${user.name}`;

        const portalRoleBadge = document.getElementById('portal-user-role-badge');
        if (portalRoleBadge) portalRoleBadge.textContent = user.role || 'Supervisor Técnico DIAT';

        // Badge de seguridad de contraseña
        const isCustomized = (localStorage.getItem('diat_pw_changed_' + user.username) === 'true') || user.passwordCustomized;
        const secBadge = document.getElementById('portal-security-badge');
        if (secBadge) {
            if (isCustomized) {
                secBadge.className = 'portal-badge-pill portal-badge-security-ok';
                secBadge.innerHTML = '<i class="fa-solid fa-lock text-[10px]"></i><span>Contraseña Personalizada (Segura)</span>';
            } else {
                secBadge.className = 'portal-badge-pill portal-badge-security-warn';
                secBadge.innerHTML = '<i class="fa-solid fa-triangle-exclamation text-[10px]"></i><span>Clave Provisional DIAT2026 (Cambiar)</span>';
            }
        }

        // Subregiones cubiertas por el supervisor
        const supervisorRows = getSupervisorRows();
        const subregionsSet = new Set(supervisorRows.map(r => r['SUBREGION']).filter(Boolean));
        const subregionsList = Array.from(subregionsSet);
        const subregionsEl = document.getElementById('portal-user-subregions');
        if (subregionsEl) {
            subregionsEl.textContent = subregionsList.length > 0 ? subregionsList.join(' • ') : 'Antioquia Central';
        }

        // Ficha del Perfil en Sub-pestaña Mi Perfil
        const pfName = document.getElementById('portal-profile-fullname');
        if (pfName) pfName.textContent = user.name;
        const pfUserVal = document.getElementById('portal-profile-username-val');
        if (pfUserVal) pfUserVal.textContent = user.username;
        const pfCount = document.getElementById('portal-profile-conv-count');
        if (pfCount) pfCount.textContent = supervisorRows.length;

        if (unauthorized) unauthorized.classList.add('hidden');
        if (authorized) authorized.classList.remove('hidden');

        renderSupervisorPortal();
    } else {
        if (btnLoginTrigger) btnLoginTrigger.classList.remove('hidden');
        if (headerName) headerName.textContent = 'Supervisión DIAT';
        if (headerRole) headerRole.textContent = 'Equipo Técnico';
        if (headerAvatarImg) {
            headerAvatarImg.src = './assets/perfil_equipo.jpg';
        }
        if (ddName) ddName.textContent = 'Supervisión DIAT';
        if (ddRole) ddRole.textContent = 'Equipo Técnico';

        if (unauthorized) unauthorized.classList.remove('hidden');
        if (authorized) authorized.classList.add('hidden');
    }
}

// Cierra la sesión
function handleLogout() {
    localStorage.removeItem('diat_logged_user');
    sessionStorage.removeItem('diat_logged_user');
    sessionStorage.removeItem('diat_admin_authorized');
    window.diatAdminAuthorized = false;
    checkAuthStatus();

    // Regresar a la pestaña principal (Resumen)
    const resumenTabBtn = document.querySelector('.tab-btn[data-tab="resumen"]');
    if (resumenTabBtn) resumenTabBtn.click();

    alertToast("Sesión Cerrada", "Has salido del portal de supervisores.");
}

// Renderización de la pestaña portal si está activa
function checkAndRenderPortal() {
    const user = getLoggedUser();
    if (user) {
        renderSupervisorPortal();
    }
}

// Renderizado principal del dashboard y subpestañas del Portal del Supervisor
function renderSupervisorPortal() {
    const supervisorRows = getSupervisorRows();

    // 1. Calcular KPIs Contractuales y Físicos
    let activos = 0, porLiquidar = 0, finalizados = 0, sumInv = 0, sumLong = 0, sumArea = 0;
    let sumFisico = 0;

    supervisorRows.forEach(r => {
        const state = getSystemState(r['ESTADO CONVENIO']).label;
        if (state === 'En Ejecución') activos++;
        else if (state === 'Por Liquidar') porLiquidar++;
        else if (state === 'Liquidado' || state === 'Ejecutado') finalizados++;

        sumInv += (r['APORTE DEPARTAMENTO'] || 0) + (r['ADICION DEPARTAMENTO'] || 0);
        sumLong += getRowLongitudEjecutada(r);
        sumArea += getRowAreaEjecutada(r);
        sumFisico += (r['FISICO_NORM'] || 0);
    });

    const avgFisico = supervisorRows.length > 0 ? (sumFisico / supervisorRows.length) : 0;

    // 2. Visitas Técnicas asignadas a este supervisor
    const allVisits = window.DIATDataService ? window.DIATDataService.getTechnicalVisits() : [];
    const assignedIds = supervisorRows.map(r => String(r['CONVENIO']).trim());
    const supervisorVisits = allVisits.filter(v => assignedIds.includes(String(v.convenioId).trim()));
    const realizadasCount = supervisorVisits.filter(v => v.estado !== 'Programada').length;
    const programadasCount = supervisorVisits.filter(v => v.estado === 'Programada').length;

    // 3. Alertas específicas y desgloses
    const today = new Date();
    let vencidosCount = 0, desfasesCount = 0;
    supervisorRows.forEach(r => {
        const estStr = String(r['ESTADO CONVENIO'] || '').toLowerCase();
        if (estStr.includes('liquidado') || estStr.includes('resciliado')) return;

        let termStr = r['NUEVA FECHA DE TERMINACION'] || r['FECHA DE TERMINACION'];
        let termDate = parseCOPDate(termStr);
        const f = r['FISICO_NORM'] || 0;
        const fin = r['FINANCIERO_NORM'] || 0;

        if (termDate) {
            const msLeft = termDate.getTime() - today.getTime();
            const daysLeft = Math.ceil(msLeft / (1000 * 60 * 60 * 24));
            if (daysLeft <= 30) vencidosCount++;
        }
        if (fin > f + 15) desfasesCount++;
    });

    const totalAlerts = vencidosCount + desfasesCount;

    // Escribir KPIs en HTML
    const setTxt = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };

    // Hero Cards
    setTxt('kpi-port-total', supervisorRows.length);
    setTxt('kpi-port-ejec', activos);
    setTxt('kpi-port-liq', porLiquidar);
    setTxt('kpi-port-fin', finalizados);

    setTxt('kpi-port-avg-fisico', avgFisico.toFixed(1) + '%');
    const barFisico = document.getElementById('kpi-port-avg-bar');
    if (barFisico) barFisico.style.width = Math.min(100, Math.max(0, avgFisico)) + '%';

    setTxt('kpi-port-visitas-total', supervisorVisits.length);
    setTxt('kpi-port-visitas-realizadas', realizadasCount);
    setTxt('kpi-port-visitas-programadas', programadasCount);

    setTxt('kpi-port-venc', totalAlerts);
    setTxt('kpi-port-alertas-vencidos', vencidosCount);
    setTxt('kpi-port-alertas-desfases', desfasesCount);

    // Barra secundaria
    setTxt('kpi-port-inv', formatCurrency(sumInv));
    setTxt('kpi-port-long', formatNumber(sumLong) + ' m');
    setTxt('kpi-port-area', formatNumber(sumArea) + ' m²');
    setTxt('kpi-port-update', 'Corte: ' + new Date().toLocaleDateString('es-CO'));

    // Badges en pestañas de subnavegación
    setTxt('badge-count-convenios', supervisorRows.length);
    setTxt('badge-count-visitas', supervisorVisits.length);
    setTxt('badge-count-alertas', totalAlerts);

    // 4. Renderizar subpestañas y gráficos
    renderSupervisorCharts(supervisorRows);
    renderSupervisorConvenios(supervisorRows);
    renderSupervisorAlertas(supervisorRows);
    renderSupervisorVisitasTable(supervisorRows);
    renderSupervisorHistorialTable(supervisorRows);

    // 5. Configuración diferenciada para ADMINISTRADOR vs SUPERVISOR
    const loggedU = getLoggedUser();
    const isAdmin = (loggedU && (loggedU.username === 'ADMIN' || (loggedU.role && loggedU.role.toUpperCase().includes('ADMIN')))) || window.diatAdminAuthorized;

    const adminToolbar = document.getElementById('portal-admin-toolbar');
    const adminFilterSelect = document.getElementById('portal-admin-supervisor-filter');
    const supervisoresSubtabBtn = document.getElementById('btn-portal-subtab-supervisores');
    const auditSubtabBtn = document.getElementById('btn-portal-subtab-auditoria');
    const conveniosSubtabLabel = document.getElementById('portal-subtab-convenios-label');
    const welcomeTitle = document.getElementById('portal-welcome-title');
    const roleBadge = document.getElementById('portal-user-role-badge');
    const subregionsBadge = document.getElementById('portal-user-subregions');

    if (isAdmin) {
        if (welcomeTitle) welcomeTitle.textContent = 'Panel de Control Administrativo — DIAT Antioquia';
        if (roleBadge) roleBadge.textContent = 'Superadministrador DIAT (Acceso Total)';
        if (subregionsBadge) subregionsBadge.textContent = '125 Municipios • 9 Subregiones';
        if (conveniosSubtabLabel) conveniosSubtabLabel.textContent = 'Todos los Convenios';

        if (adminToolbar) adminToolbar.classList.remove('hidden');
        if (supervisoresSubtabBtn) {
            supervisoresSubtabBtn.style.display = 'inline-flex';
            const supBadge = document.getElementById('badge-count-supervisores');
            const totalSupCount = Object.keys(PORTAL_USERS).filter(k => k !== 'ADMIN').length;
            if (supBadge) supBadge.textContent = totalSupCount;
        }

        if (adminFilterSelect && adminFilterSelect.options.length <= 1) {
            populateAdminSupervisorFilter();
        }

        if (auditSubtabBtn) {
            auditSubtabBtn.style.display = 'inline-flex';
            if (window.DIATDataService) {
                window.DIATDataService.getAuditLogs(100).then(logs => {
                    const countBadge = document.getElementById('badge-count-auditoria');
                    if (countBadge) countBadge.textContent = (logs || []).length;
                }).catch(() => { });
            }
        }
    } else {
        if (adminToolbar) adminToolbar.classList.add('hidden');
        if (supervisoresSubtabBtn) supervisoresSubtabBtn.style.display = 'none';
        if (auditSubtabBtn) auditSubtabBtn.style.display = 'none';
        if (conveniosSubtabLabel) conveniosSubtabLabel.textContent = 'Mis Convenios';
        if (welcomeTitle && loggedU) welcomeTitle.textContent = `Bienvenido, ${loggedU.name}`;
        if (roleBadge && loggedU) roleBadge.textContent = loggedU.role || 'Supervisor Técnico DIAT';
        if (subregionsBadge && loggedU) {
            const myRows = rawData.filter(r => normalizeSupervisorName(r['SUPERVISOR']) === normalizeSupervisorName(loggedU.supervisorExcelName || loggedU.name));
            const subregiones = [...new Set(myRows.map(r => r['SUBREGION']).filter(Boolean))];
            subregionsBadge.textContent = subregiones.length > 0 ? subregiones.join(', ') : 'Subregiones Asignadas';
        }
    }
}

// Variable global para almacenar las instancias de los gráficos del portal del supervisor
window.portalCharts = {};

function renderSupervisorCharts(supervisorRows) {
    // 1. Chart - Distribución por Estado Contractual
    const estadosCount = {};
    supervisorRows.forEach(r => {
        const label = getSystemState(r['ESTADO CONVENIO']).label || 'Otros';
        estadosCount[label] = (estadosCount[label] || 0) + 1;
    });

    const canvasEstados = document.getElementById('chart-port-estados');
    if (canvasEstados) {
        if (window.portalCharts['estados']) {
            window.portalCharts['estados'].destroy();
        }

        const labels = Object.keys(estadosCount);
        const data = Object.values(estadosCount);

        const colorPalette = {
            'En Ejecución': '#0B5640',
            'Por Liquidar': '#F28E18',
            'Liquidado': '#3561AB',
            'Ejecutado': '#38BDF8',
            'Suspendido': '#94A3B8'
        };
        const backgroundColors = labels.map(l => colorPalette[l] || '#64748B');

        const ctx = canvasEstados.getContext('2d');
        window.portalCharts['estados'] = new Chart(ctx, {
            type: 'doughnut',
            data: {
                labels: labels,
                datasets: [{
                    data: data,
                    backgroundColor: backgroundColors,
                    borderWidth: 2,
                    borderColor: '#ffffff'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        position: 'bottom',
                        labels: {
                            font: { family: 'Poppins', size: 10, weight: 'bold' },
                            color: '#475569',
                            padding: 12
                        }
                    },
                    tooltip: {
                        backgroundColor: 'rgba(15, 23, 42, 0.9)',
                        padding: 10,
                        titleFont: { family: 'Poppins', size: 11, weight: 'bold' },
                        bodyFont: { family: 'Poppins', size: 12 },
                        cornerRadius: 8
                    }
                },
                cutout: '65%'
            }
        });
    }

    // 2. Chart - Avance Físico vs Financiero por Convenio
    const canvasAvances = document.getElementById('chart-port-avances');
    if (canvasAvances) {
        if (window.portalCharts['avances']) {
            window.portalCharts['avances'].destroy();
        }

        const sortedRows = [...supervisorRows].slice(0, 10);
        const ids = sortedRows.map(r => `Conv. ${String(r['CONVENIO']).trim().slice(-6)}`);
        const fisicos = sortedRows.map(r => parseFloat(r['FISICO_NORM']) || 0);
        const financieros = sortedRows.map(r => parseFloat(r['FINANCIERO_NORM']) || 0);

        const ctx = canvasAvances.getContext('2d');
        window.portalCharts['avances'] = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: ids,
                datasets: [
                    {
                        label: 'Avance Físico (%)',
                        data: fisicos,
                        backgroundColor: '#0B5640',
                        borderRadius: 6,
                        borderWidth: 0
                    },
                    {
                        label: 'Avance Financiero (%)',
                        data: financieros,
                        backgroundColor: '#3561AB',
                        borderRadius: 6,
                        borderWidth: 0
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        position: 'bottom',
                        labels: {
                            font: { family: 'Poppins', size: 10, weight: 'bold' },
                            color: '#475569',
                            padding: 12
                        }
                    },
                    tooltip: {
                        backgroundColor: 'rgba(15, 23, 42, 0.9)',
                        padding: 10,
                        titleFont: { family: 'Poppins', size: 11, weight: 'bold' },
                        bodyFont: { family: 'Poppins', size: 12 },
                        cornerRadius: 8,
                        callbacks: {
                            label: function (context) {
                                return ` ${context.dataset.label}: ${context.raw.toFixed(1)}%`;
                            }
                        }
                    }
                },
                scales: {
                    x: {
                        grid: { display: false },
                        ticks: {
                            font: { family: 'Poppins', size: 9, weight: 'bold' },
                            color: '#64748B'
                        }
                    },
                    y: {
                        beginAtZero: true,
                        max: 100,
                        grid: { color: '#F1F5F9' },
                        ticks: {
                            font: { family: 'Poppins', size: 9 },
                            color: '#64748B',
                            callback: function (value) { return value + '%'; }
                        }
                    }
                }
            }
        });
    }
}

// Filtra dinámicamente los convenios del supervisor con el buscador y chips
window.filterSupervisorConvenios = function () {
    const supervisorRows = getSupervisorRows();
    const searchInp = document.getElementById('portal-convenios-search');
    const query = searchInp ? searchInp.value.trim().toLowerCase() : '';

    const activeChip = document.querySelector('.portal-filter-chip.active');
    const filterType = activeChip ? activeChip.getAttribute('data-filter') : 'all';

    let filtered = supervisorRows.filter(r => {
        // Filtro por texto de búsqueda
        if (query) {
            const id = String(r['CONVENIO'] || '').toLowerCase();
            const mun = String(r['MUNICIPIO'] || '').toLowerCase();
            const obj = String(r['OBJETO'] || '').toLowerCase();
            if (!id.includes(query) && !mun.includes(query) && !obj.includes(query)) {
                return false;
            }
        }

        // Filtro por chip de categoría
        const state = getSystemState(r['ESTADO CONVENIO']).label;
        if (filterType === 'ejecucion') return state === 'En Ejecución';
        if (filterType === 'liquidar') return state === 'Por Liquidar';
        if (filterType === 'finalizado') return state === 'Liquidado' || state === 'Ejecutado';
        if (filterType === 'alerta') {
            const fin = r['FINANCIERO_NORM'] || 0;
            const fis = r['FISICO_NORM'] || 0;
            return fin > fis + 15;
        }
        if (filterType === 'sin-fotos') {
            return !hasConvenioPhotographicRecord(String(r['CONVENIO']).trim());
        }

        return true;
    });

    renderSupervisorConveniosGrid(filtered);
};

// Renderiza las tarjetas enriquecidas de convenios asignados (v2)
function renderSupervisorConvenios(supervisorRows) {
    renderSupervisorConveniosGrid(supervisorRows);
}

function renderSupervisorConveniosGrid(rows) {
    const grid = document.getElementById('portal-convenios-grid');
    if (!grid) return;
    grid.innerHTML = '';

    if (typeof window.prefetchConvenioPhotos === 'function' && Array.isArray(rows) && rows.length > 0) {
        window.prefetchConvenioPhotos(rows.map(r => r['CONVENIO']));
    }

    if (!rows || rows.length === 0) {
        grid.innerHTML = `
            <div class="col-span-full text-center py-16 px-4 bg-white rounded-2xl border border-slate-200">
                <i class="fa-solid fa-folder-open text-slate-300 text-4xl mb-3 block"></i>
                <p class="text-slate-600 font-bold text-sm">No se encontraron convenios que coincidan con la búsqueda o filtro.</p>
                <p class="text-slate-400 text-xs mt-1">Prueba cambiando los criterios en la barra superior.</p>
            </div>
        `;
        return;
    }

    rows.forEach(row => {
        const id = String(row['CONVENIO']).trim();
        const municipio = row['MUNICIPIO'] || 'N/A';
        const subregion = row['SUBREGION'] || '';
        const fisico = row['FISICO_NORM'] || 0;
        const financiero = row['FINANCIERO_NORM'] || 0;
        const valorTotal = (row['VALOR TOTAL'] || 0);
        const objeto = row['OBJETO'] || 'Sin descripción u objeto registrado';
        const truncatedObjeto = objeto.length > 130 ? objeto.substring(0, 130) + '...' : objeto;
        const estado = row['ESTADO CONVENIO'] || 'En Ejecución';
        const sysState = getSystemState(estado);
        const hasDesfase = financiero > fisico + 15;

        // Estado del registro fotográfico del convenio
        const photoData = getConvenioPhotosData(id);
        const hasPhotos = photoData.total > 0;
        const photoAlertHtml = hasPhotos ? `
            <div class="portal-convenio-photos-badge">
                <span class="flex items-center gap-1.5 truncate">
                    <i class="fa-solid fa-camera text-institutional-primary"></i>
                    <span><strong>${photoData.total}</strong> foto${photoData.total > 1 ? 's' : ''} (${photoData.antes.length} ant / ${photoData.durante.length} dur / ${photoData.despues.length} desp)</span>
                </span>
                <button type="button" class="text-[10px] font-black text-institutional-primary hover:underline shrink-0" onclick="openConvenioPhotoManager('${id}')">Gestionar</button>
            </div>
        ` : `
            <div class="portal-convenio-alert-no-photos">
                <span class="flex items-center gap-1.5">
                    <i class="fa-solid fa-triangle-exclamation text-amber-500 text-xs"></i>
                    <span>Sin registro fotográfico</span>
                </span>
                <button type="button" class="text-[10px] font-black text-amber-800 underline hover:text-amber-950 shrink-0" onclick="openConvenioPhotoManager('${id}')">Cargar Fotos</button>
            </div>
        `;

        const card = document.createElement('div');
        card.className = 'portal-convenio-card-v2';
        card.innerHTML = `
            <div>
                <!-- Header Card -->
                <div class="portal-card-header-bar">
                    <div>
                        <span class="portal-card-id-badge">
                            <i class="fa-solid fa-hashtag text-slate-400 text-xs"></i>
                            ${id}
                            <button type="button" class="portal-card-btn-copy" onclick="copyConvenioId('${id}')" title="Copiar número de convenio">
                                <i class="fa-regular fa-copy"></i>
                            </button>
                        </span>
                        <div class="flex items-center gap-1.5 mt-1 flex-wrap">
                            <span class="text-xs font-black text-slate-700 flex items-center gap-1">
                                <i class="fa-solid fa-location-dot text-institutional-primary text-[11px]"></i>
                                ${municipio}
                            </span>
                            ${subregion ? `<span class="text-[9.5px] font-bold text-slate-400 bg-slate-100 px-1.5 py-0.5 rounded">${subregion}</span>` : ''}
                            ${row['SUPERVISOR'] ? `<span class="text-[9.5px] font-bold text-amber-800 bg-amber-50 border border-amber-200 px-1.5 py-0.5 rounded flex items-center gap-1 truncate max-w-[170px]" title="Supervisor Asignado: ${row['SUPERVISOR']}"><i class="fa-solid fa-user-tie text-[9px] text-amber-600"></i>${row['SUPERVISOR']}</span>` : ''}
                        </div>
                    </div>
                    <span class="badge-estado ${sysState.badgeClass} text-[9.5px] font-extrabold uppercase tracking-wider">
                        ${sysState.label}
                    </span>
                </div>

                <!-- Objeto -->
                <div class="mb-3.5">
                    <p class="text-xs text-slate-500 font-medium leading-relaxed" title="${objeto.replace(/"/g, '&quot;')}">
                        ${truncatedObjeto}
                    </p>
                    <p class="text-[11px] font-bold text-slate-700 mt-2 flex items-center justify-between">
                        <span class="text-slate-400 font-semibold uppercase text-[10px]">Valor Total:</span>
                        <span class="text-slate-900 font-black">${formatCurrency(valorTotal)}</span>
                    </p>
                </div>

                <!-- Medidores de Avance Dual -->
                <div class="portal-dual-progress-wrap">
                    <div class="space-y-2.5">
                        <div>
                            <div class="flex justify-between items-center text-[10.5px] font-bold mb-1">
                                <span class="text-slate-500 uppercase flex items-center gap-1">
                                    <span class="w-2 h-2 rounded-full bg-emerald-600 inline-block"></span>
                                    Avance Físico
                                </span>
                                <span class="text-institutional-primary font-black">${fisico.toFixed(1)}%</span>
                            </div>
                            <div class="w-full bg-slate-200/80 h-2 rounded-full overflow-hidden">
                                <div class="h-full rounded-full transition-all duration-500" style="width: ${Math.min(100, Math.max(0, fisico))}%; background-color: #0B5640;"></div>
                            </div>
                        </div>

                        <div>
                            <div class="flex justify-between items-center text-[10.5px] font-bold mb-1">
                                <span class="text-slate-500 uppercase flex items-center gap-1">
                                    <span class="w-2 h-2 rounded-full bg-blue-600 inline-block"></span>
                                    Avance Financiero
                                </span>
                                <span class="text-blue-700 font-black">${financiero.toFixed(1)}%</span>
                            </div>
                            <div class="w-full bg-slate-200/80 h-2 rounded-full overflow-hidden">
                                <div class="bg-blue-600 h-full rounded-full transition-all duration-500" style="width: ${Math.min(100, Math.max(0, financiero))}%;"></div>
                            </div>
                        </div>
                    </div>

                    ${hasDesfase ? `
                        <div class="mt-2.5 pt-2 border-t border-red-100 flex items-center justify-between text-[10px] font-bold text-red-600">
                            <span class="flex items-center gap-1"><i class="fa-solid fa-triangle-exclamation"></i> Desfase Crítico</span>
                            <span>+${(financiero - fisico).toFixed(1)}% financiero</span>
                        </div>
                    ` : ''}

                    ${photoAlertHtml}
                </div>
            </div>

            <!-- Acciones Rápidas -->
            <div class="portal-card-actions-bar">
                <div class="portal-card-actions-grid">
                    <button type="button" class="portal-card-btn-edit" onclick="openEditConvenioModal('${id}')">
                        <i class="fa-solid fa-pen-to-square text-xs"></i>
                        <span>Actualizar</span>
                    </button>
                    <button type="button" class="portal-card-btn-photos" onclick="openConvenioPhotoManager('${id}')" title="Administrar Registro Fotográfico (Antes, Durante, Después)">
                        <i class="fa-solid fa-camera-retro text-xs"></i>
                        <span>Fotos</span>
                    </button>
                    <button type="button" class="portal-card-btn-visit" onclick="openNewVisitForConvenio('${id}')">
                        <i class="fa-solid fa-calendar-plus text-xs"></i>
                        <span>+ Visita</span>
                    </button>
                </div>
                <button type="button" class="portal-card-btn-detail" onclick="openConvenioDetailById('${id}')" title="Ver ficha técnica completa">
                    <i class="fa-solid fa-arrow-up-right-from-square text-xs text-institutional-primary"></i>
                    <span>Ver Ficha Técnica</span>
                </button>
            </div>
        `;
        grid.appendChild(card);
    });
}

// =========================================================================
// MÓDULO DE GESTIÓN FOTOGRÁFICA DEL CONVENIO (PORTAL SUPERVISOR)
// =========================================================================
window.activePhotoMgrConvenioId = null;
window.activePhotoMgrViewStage = 'todas';
window.activePhotoMgrUploadStage = 'durante';

window.openConvenioPhotoManager = async function (convenioId) {
    const currentUser = getLoggedUser();
    if (window.DIATDataService && !window.DIATDataService.hasPermission(currentUser, 'canManagePhotos')) {
        alertToast('Acceso Denegado', 'No tienes permisos asignados para gestionar fotografías.', 'warning');
        return;
    }

    const cid = String(convenioId).trim();
    window.activePhotoMgrConvenioId = cid;
    window.activePhotoMgrViewStage = 'todas';
    window.activePhotoMgrUploadStage = 'durante';

    const modal = document.getElementById('modal-gestionar-fotos-convenio');
    if (!modal) return;

    const row = (rawData || []).find(r => String(r['CONVENIO']).trim() === cid) || {};
    const municipio = row['MUNICIPIO'] || 'Antioquia';
    const objeto = row['OBJETO'] || 'Sin descripción de objeto registrado';

    const titleId = document.getElementById('photo-mgr-convenio-id');
    if (titleId) titleId.textContent = cid;

    const subtitle = document.getElementById('photo-mgr-subtitle');
    if (subtitle) subtitle.textContent = `${municipio} — ${objeto.length > 90 ? objeto.substring(0, 90) + '...' : objeto}`;

    // Reset upload stage buttons
    document.querySelectorAll('.photo-upload-stage-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.stage === window.activePhotoMgrUploadStage);
    });

    // Reset view tabs
    document.querySelectorAll('.photo-mgr-tab').forEach(tab => {
        tab.classList.toggle('active', tab.dataset.stage === 'todas');
    });

    modal.classList.remove('hidden');
    modal.style.display = 'flex';
    document.body.style.overflow = 'hidden';

    // Intento de pre-cargar desde caché local o memoria para render inmediato
    if (!window.DIAT_DRIVE_PHOTOS_CACHE[cid]) {
        try {
            const raw = localStorage.getItem('diat_drive_cache_' + cid) || sessionStorage.getItem('diat_drive_cache_' + cid);
            if (raw) {
                window.DIAT_DRIVE_PHOTOS_CACHE[cid] = JSON.parse(raw);
            }
        } catch (e) { }
    }

    if (!window.DIAT_DRIVE_PHOTOS_CACHE[cid]) {
        try {
            const scriptUrl = `https://script.google.com/macros/s/AKfycbwXBFslIOCwVCyAae8-FG0VL5pqotLkjejwJhavm5xoGU4SlyVETwRkGCmDNVkcRPw4/exec?convenio=${encodeURIComponent(cid)}`;
            fetch(scriptUrl).then(r => r.ok ? r.json() : null).then(idx => {
                if (idx && ((idx.antes && idx.antes.length > 0) || (idx.durante && idx.durante.length > 0) || (idx.despues && idx.despues.length > 0))) {
                    window.DIAT_DRIVE_PHOTOS_CACHE[cid] = idx;
                    try {
                        localStorage.setItem('diat_drive_cache_' + cid, JSON.stringify(idx));
                        sessionStorage.setItem('diat_drive_cache_' + cid, JSON.stringify(idx));
                    } catch (e) { }
                    renderPhotoManagerGallery();
                }
            }).catch(() => { });
        } catch (e) { }
    }

    renderPhotoManagerGallery();
};

window.closeConvenioPhotoManager = function () {
    const modal = document.getElementById('modal-gestionar-fotos-convenio');
    if (modal) {
        modal.classList.add('hidden');
        modal.style.display = 'none';
    }
    document.body.style.overflow = 'auto';
    window.activePhotoMgrConvenioId = null;
    // Refrescar tarjetas del supervisor para actualizar alertas/contadores
    if (typeof filterSupervisorConvenios === 'function') {
        filterSupervisorConvenios();
    }
};

function renderPhotoManagerGallery() {
    const cid = window.activePhotoMgrConvenioId;
    if (!cid) return;

    const data = getConvenioPhotosData(cid);

    // Actualizar contadores en tabs
    const cTodas = document.getElementById('photo-count-todas');
    const cAntes = document.getElementById('photo-count-antes');
    const cDurante = document.getElementById('photo-count-durante');
    const cDespues = document.getElementById('photo-count-despues');
    if (cTodas) cTodas.textContent = data.total;
    if (cAntes) cAntes.textContent = data.antes.length;
    if (cDurante) cDurante.textContent = data.durante.length;
    if (cDespues) cDespues.textContent = data.despues.length;

    const statusBadge = document.getElementById('photo-mgr-status-badge');
    if (statusBadge) {
        statusBadge.textContent = `${data.total} foto${data.total !== 1 ? 's' : ''}`;
        statusBadge.className = data.total > 0
            ? 'px-2 py-0.5 text-[10px] font-black rounded-full bg-emerald-100 text-emerald-800'
            : 'px-2 py-0.5 text-[10px] font-black rounded-full bg-amber-100 text-amber-800';
    }

    const grid = document.getElementById('photo-mgr-gallery-grid');
    const countLabel = document.getElementById('photo-mgr-gallery-count');
    const galleryTitle = document.getElementById('photo-mgr-gallery-title');
    if (!grid) return;
    grid.innerHTML = '';

    const stage = window.activePhotoMgrViewStage || 'todas';

    let photosToDisplay = [];
    if (stage === 'todas') {
        data.antes.forEach((p, i) => photosToDisplay.push({ src: p, stage: 'Antes', stageKey: 'antes', idx: i }));
        data.durante.forEach((p, i) => photosToDisplay.push({ src: p, stage: 'Durante', stageKey: 'durante', idx: i }));
        data.despues.forEach((p, i) => photosToDisplay.push({ src: p, stage: 'Después', stageKey: 'despues', idx: i }));
        if (galleryTitle) galleryTitle.textContent = 'Galería de Evidencias (Todas las Etapas)';
    } else {
        const list = data[stage] || [];
        const label = stage === 'antes' ? 'Antes' : (stage === 'durante' ? 'Durante' : 'Después');
        list.forEach((p, i) => photosToDisplay.push({ src: p, stage: label, stageKey: stage, idx: i }));
        if (galleryTitle) galleryTitle.textContent = `Galería de Evidencias — Etapa ${label}`;
    }

    if (countLabel) countLabel.textContent = `${photosToDisplay.length} foto${photosToDisplay.length !== 1 ? 's' : ''} encontrada${photosToDisplay.length !== 1 ? 's' : ''}`;

    if (photosToDisplay.length === 0) {
        grid.innerHTML = `
            <div class="col-span-full py-10 px-4 text-center bg-slate-50 rounded-xl border border-dashed border-slate-200">
                <i class="fa-solid fa-camera-retro text-slate-300 text-3xl mb-2.5 block"></i>
                <p class="text-xs font-bold text-slate-600">No hay fotografías registradas en esta etapa.</p>
                <p class="text-[11px] text-slate-400 mt-1">Arrastra o selecciona fotos arriba para agregarlas a la carpeta del convenio en Google Drive.</p>
            </div>
        `;
        return;
    }

    photosToDisplay.forEach(item => {
        const card = document.createElement('div');
        card.className = 'photo-card-item group';
        const fastSrc = (typeof getFastDriveImageUrl === 'function') ? getFastDriveImageUrl(item.src, 320) : item.src;

        card.innerHTML = `
            <img src="${fastSrc}" alt="Foto Convenio ${cid}" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="if(this.src!=='${item.src}'){this.src='${item.src}';}" />
            <span class="photo-card-stage-pill">${item.stage}</span>
            <button type="button" class="photo-card-delete-btn" title="Eliminar foto" onclick="window.deletePhotoFromConvenio('${item.stageKey}', ${item.idx})">
                <i class="fa-solid fa-trash"></i>
            </button>
        `;

        card.querySelector('img').addEventListener('click', () => {
            currentGalleryImages = photosToDisplay.map(p => (typeof getFastDriveImageUrl === 'function' ? getFastDriveImageUrl(p.src, 1600) : p.src));
            const imgIdx = photosToDisplay.indexOf(item);
            openLightbox(imgIdx >= 0 ? imgIdx : 0);
        });

        grid.appendChild(card);
    });
}

window.deletePhotoFromConvenio = function (stageKey, index) {
    const cid = window.activePhotoMgrConvenioId;
    if (!cid) return;

    if (!confirm('¿Estás seguro de eliminar esta fotografía del registro del convenio?')) {
        return;
    }

    try {
        let stored = localStorage.getItem('diat_photos_' + cid);
        let parsed = stored ? JSON.parse(stored) : { antes: [], durante: [], despues: [] };
        if (Array.isArray(parsed)) {
            parsed.splice(index, 1);
            localStorage.setItem('diat_photos_' + cid, JSON.stringify(parsed));
        } else if (parsed && parsed[stageKey]) {
            parsed[stageKey].splice(index, 1);
            localStorage.setItem('diat_photos_' + cid, JSON.stringify(parsed));
        }

        if (window.DIAT_DRIVE_PHOTOS_CACHE[cid] && window.DIAT_DRIVE_PHOTOS_CACHE[cid][stageKey]) {
            window.DIAT_DRIVE_PHOTOS_CACHE[cid][stageKey].splice(index, 1);
        }

        renderPhotoManagerGallery();
        if (typeof filterSupervisorConvenios === 'function') {
            filterSupervisorConvenios();
        }
        alertToast('Foto Eliminada', 'La fotografía ha sido removida del registro.', 'info');
    } catch (e) {
        console.error("Error eliminando foto:", e);
    }
};

function setupPhotoManagerEvents() {
    const closeBtn = document.getElementById('btn-close-photo-mgr');
    const closeFooter = document.getElementById('btn-close-photo-mgr-footer');
    if (closeBtn) closeBtn.addEventListener('click', window.closeConvenioPhotoManager);
    if (closeFooter) closeFooter.addEventListener('click', window.closeConvenioPhotoManager);

    // Selector de etapas para visualización (Todas, Antes, Durante, Después)
    document.querySelectorAll('.photo-mgr-tab').forEach(tab => {
        tab.addEventListener('click', () => {
            document.querySelectorAll('.photo-mgr-tab').forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            window.activePhotoMgrViewStage = tab.dataset.stage;
            renderPhotoManagerGallery();
        });
    });

    // Selector de etapa para carga (Antes, Durante, Después)
    document.querySelectorAll('.photo-upload-stage-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.photo-upload-stage-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            window.activePhotoMgrUploadStage = btn.dataset.stage;
        });
    });

    // Input de archivos y Drag & Drop
    const fileInput = document.getElementById('photo-mgr-file-input');
    const dropzone = document.getElementById('photo-mgr-dropzone');

    if (dropzone && fileInput) {
        dropzone.addEventListener('dragover', (e) => {
            e.preventDefault();
            dropzone.classList.add('border-emerald-500', 'bg-emerald-50/50');
        });
        dropzone.addEventListener('dragleave', () => {
            dropzone.classList.remove('border-emerald-500', 'bg-emerald-50/50');
        });
        dropzone.addEventListener('drop', (e) => {
            e.preventDefault();
            dropzone.classList.remove('border-emerald-500', 'bg-emerald-50/50');
            if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
                handlePhotoManagerFiles(Array.from(e.dataTransfer.files));
            }
        });

        fileInput.addEventListener('change', (e) => {
            if (e.target.files && e.target.files.length > 0) {
                handlePhotoManagerFiles(Array.from(e.target.files));
                e.target.value = '';
            }
        });
    }
}

async function handlePhotoManagerFiles(files) {
    const cid = window.activePhotoMgrConvenioId;
    if (!cid || files.length === 0) return;

    const stage = window.activePhotoMgrUploadStage || 'durante';
    const progressContainer = document.getElementById('photo-mgr-progress-container');
    const progressBar = document.getElementById('photo-mgr-progress-bar');
    const progressPct = document.getElementById('photo-mgr-progress-pct');
    const progressText = document.getElementById('photo-mgr-progress-text');

    if (progressContainer) {
        progressContainer.classList.remove('hidden');
        if (progressBar) progressBar.style.width = '25%';
        if (progressPct) progressPct.textContent = '25%';
        if (progressText) progressText.innerHTML = '<i class="fa-solid fa-spinner fa-spin text-institutional-primary mr-1"></i>Comprimiendo y preparando fotografías en paralelo...';
    }

    const stageLabel = stage === 'antes' ? 'Antes' : (stage === 'durante' ? 'Durante' : 'Después');

    let current = getConvenioPhotosData(cid);
    let stageList = current[stage] || [];

    try {
        // 1. Compresión ultra rápida y simultánea de todas las imágenes seleccionadas
        const compressedResults = await Promise.all(files.map(async (file) => {
            try {
                const comp = await compressImage(file, 1280, 1280, 0.78);
                return { file, data: comp };
            } catch (err) {
                console.warn("Error comprimiendo archivo:", file.name, err);
                return null;
            }
        }));

        const validResults = compressedResults.filter(Boolean);
        validResults.forEach(r => stageList.push(r.data));

        if (progressBar) progressBar.style.width = '70%';
        if (progressPct) progressPct.textContent = '70%';
        if (progressText) progressText.innerHTML = '<i class="fa-solid fa-cloud-arrow-up text-institutional-primary mr-1"></i>Sincronizando con Google Drive en segundo plano...';

        // 2. Actualización instantánea (Optimistic UI Update: 0 ms de espera para el usuario)
        current[stage] = stageList;
        const serialized = JSON.stringify({
            antes: current.antes,
            durante: current.durante,
            despues: current.despues
        });
        localStorage.setItem('diat_photos_' + cid, serialized);
        localStorage.setItem('diat_drive_cache_' + cid, serialized);

        window.DIAT_DRIVE_PHOTOS_CACHE[cid] = {
            antes: current.antes,
            durante: current.durante,
            despues: current.despues
        };

        // Renderizar inmediatamente la galería para que el usuario las vea ya mismo
        renderPhotoManagerGallery();
        if (typeof filterSupervisorConvenios === 'function') {
            filterSupervisorConvenios();
        }

        // 3. Subida paralela asíncrona hacia Google Apps Script (Drive) sin bloquear la interfaz
        const GOOGLE_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbwXBFslIOCwVCyAae8-FG0VL5pqotLkjejwJhavm5xoGU4SlyVETwRkGCmDNVkcRPw4/exec";
        validResults.forEach(item => {
            fetch(GOOGLE_SCRIPT_URL, {
                method: "POST",
                mode: "no-cors",
                headers: { "Content-Type": "text/plain;charset=utf-8" },
                body: JSON.stringify({
                    action: "uploadPhoto",
                    convenio: cid,
                    stage: stage,
                    fileName: item.file.name,
                    fileData: item.data
                })
            }).catch(err => console.warn("Aviso subiendo a Drive:", err));

            if (window.DIATDataService && typeof window.DIATDataService.uploadPhotoToStorage === 'function') {
                window.DIATDataService.uploadPhotoToStorage(item.data, `${cid}_${stage}`).catch(() => { });
            }
        });

        if (progressBar) progressBar.style.width = '100%';
        if (progressPct) progressPct.textContent = '100%';
        if (progressText) progressText.innerHTML = '<i class="fa-solid fa-check text-emerald-600 mr-1"></i>¡Fotografías vinculadas exitosamente!';

        setTimeout(() => {
            if (progressContainer) progressContainer.classList.add('hidden');
            alertToast('Registro Fotográfico Actualizado', `Se vincularon ${validResults.length} foto(s) en la etapa ${stageLabel} para el convenio ${cid}.`, 'success');
        }, 400);

    } catch (e) {
        console.error("Error en procesamiento de fotos:", e);
        if (progressContainer) progressContainer.classList.add('hidden');
        alertToast('Error', 'Ocurrió un inconveniente al vincular las fotos.', 'error');
    }
}

