// Carga las visitas de un convenio específico en el modal
function renderEditModalVisitsList(convenioId) {
    const list = document.getElementById('edit-visitas-list');
    if (!list) return;
    list.innerHTML = '';

    if (!window.DIATDataService) {
        list.innerHTML = `<div class="text-center py-4 text-slate-400 font-medium text-xs italic">Error de servicio de datos.</div>`;
        return;
    }

    const allVisits = window.DIATDataService.getTechnicalVisits();
    const filtered = allVisits.filter(v => String(v.convenioId).trim() === String(convenioId).trim());

    if (filtered.length === 0) {
        list.innerHTML = `<div class="text-center py-4 text-slate-400 font-medium text-xs italic">No se registran visitas técnicas previas.</div>`;
        return;
    }

    filtered.forEach(v => {
        const item = document.createElement('div');
        item.className = 'bg-slate-50 p-3 rounded-lg border border-slate-200 space-y-1 text-left';

        let photosHtml = '';
        if (v.photos && v.photos.length > 0) {
            photosHtml = `
                <div class="mt-2 grid grid-cols-4 gap-2 pt-2 border-t border-slate-200">
                    ${v.photos.map((photo, idx) => `
                        <img src="${photo}" class="w-12 h-12 object-cover rounded cursor-pointer border border-slate-200 hover:ring-2 hover:ring-institutional-light transition-all" onclick="window.openVisitPhotoLightbox('${v.id}', ${idx})" />
                    `).join('')}
                </div>
            `;
        }

        item.innerHTML = `
            <div class="flex justify-between items-center text-[10px] font-bold text-slate-400 uppercase">
                <span>Fecha: ${v.fecha}</span>
                <span class="bg-institutional-pale text-institutional-primary px-1.5 py-0.5 rounded">${v.tipo}</span>
            </div>
            <p class="text-xs font-bold text-slate-700 mt-1">${v.observaciones}</p>
            ${v.compromisos ? `<p class="text-[10px] text-slate-500"><strong class="text-slate-600">Compromisos:</strong> ${v.compromisos}</p>` : ''}
            ${v.riesgos ? `<p class="text-[10px] text-slate-500"><strong class="text-slate-600">Riesgos:</strong> ${v.riesgos}</p>` : ''}
            <div class="text-[9px] text-slate-400 mt-1 flex justify-between">
                <span>Registrado por: ${v.usuario}</span>
            </div>
            ${photosHtml}
        `;
        list.appendChild(item);
    });
}

// Carga las visitas del supervisor en la sub-pestaña del portal
function renderSupervisorVisitasTable(supervisorRows) {
    const tbody = document.getElementById('portal-visitas-table-body');
    if (!tbody) return;
    tbody.innerHTML = '';

    if (!window.DIATDataService) return;

    const allVisits = window.DIATDataService.getTechnicalVisits();
    const assignedIds = supervisorRows.map(r => String(r['CONVENIO']).trim());
    const filtered = allVisits.filter(v => assignedIds.includes(String(v.convenioId).trim()));

    if (filtered.length === 0) {
        tbody.innerHTML = `<tr><td colspan="7" class="p-6 text-center text-slate-400 font-medium text-xs italic">No se registran visitas técnicas en tus convenios.</td></tr>`;
        return;
    }

    filtered.forEach(v => {
        const tr = document.createElement('tr');
        tr.className = 'border-b border-slate-100 hover:bg-slate-50 transition-all';
        tr.style.cursor = 'pointer';

        tr.addEventListener('click', (e) => {
            if (e.target.closest('button') || e.target.closest('img')) return;
            window.openVisitDetailModal(v.id);
        });

        let photosHtml = `<span class="text-slate-400 font-bold"><i class="fa-solid fa-image mr-1"></i>0</span>`;
        if (v.photos && v.photos.length > 0) {
            photosHtml = `
                <div class="flex flex-col gap-1 items-center justify-center">
                    <button type="button" class="text-institutional-primary hover:text-institutional-light font-bold text-[10px] uppercase flex items-center gap-1" onclick="event.stopPropagation(); window.openVisitPhotoLightbox('${v.id}', 0)">
                        <i class="fa-solid fa-images"></i> Ver (${v.photos.length})
                    </button>
                    <div class="flex gap-1 justify-center max-w-[80px] overflow-hidden">
                        ${v.photos.slice(0, 3).map((p, idx) => `
                            <img src="${p}" class="w-4 h-4 object-cover rounded cursor-pointer border border-slate-200" onclick="event.stopPropagation(); window.openVisitPhotoLightbox('${v.id}', ${idx})" />
                        `).join('')}
                        ${v.photos.length > 3 ? `<span class="text-[9px] text-slate-400 font-bold">+${v.photos.length - 3}</span>` : ''}
                    </div>
                </div>
            `;
        }

        const truncate = (str, len = 80) => (str && str.length > len) ? str.slice(0, len) + '...' : (str || '--');

        tr.innerHTML = `
            <td class="p-3 font-bold text-slate-700 text-left">${v.convenioId}</td>
            <td class="p-3 whitespace-nowrap text-slate-500 text-center">${v.fecha}</td>
            <td class="p-3 text-slate-600 font-bold text-center"><span class="bg-institutional-pale text-institutional-primary px-1.5 py-0.5 rounded text-[10px]">${v.tipo}</span></td>
            <td class="p-3 text-slate-600 text-left">${truncate(v.observaciones)}</td>
            <td class="p-3 text-slate-500 text-left">${truncate(v.compromisos)}</td>
            <td class="p-3 text-slate-500 text-left">${truncate(v.riesgos)}</td>
            <td class="p-3 text-center">${photosHtml}</td>
        `;
        tbody.appendChild(tr);
    });
}

// Carga el historial de modificaciones del supervisor
function renderSupervisorHistorialTable(supervisorRows) {
    const tbody = document.getElementById('portal-historial-table-body');
    if (!tbody) return;
    tbody.innerHTML = '';

    if (!window.DIATDataService) return;

    const history = window.DIATDataService.getChangeHistory();
    const assignedIds = supervisorRows.map(r => String(r['CONVENIO']).trim());
    const filtered = history.filter(h => assignedIds.includes(String(h.convenio).trim()));

    if (filtered.length === 0) {
        tbody.innerHTML = `<tr><td colspan="6" class="p-6 text-center text-slate-400 font-medium text-xs italic">Sin modificaciones registradas recientemente.</td></tr>`;
        return;
    }

    filtered.forEach(h => {
        const tr = document.createElement('tr');
        tr.className = 'border-b border-slate-100 hover:bg-slate-50';
        tr.innerHTML = `
            <td class="p-3 text-slate-500 whitespace-nowrap">${h.fecha} ${h.hora}</td>
            <td class="p-3 font-semibold text-slate-600">${h.usuario}</td>
            <td class="p-3 font-bold text-slate-700">${h.convenio}</td>
            <td class="p-3 text-slate-600 font-bold text-left uppercase text-[10px]">${h.campo}</td>
            <td class="p-3 text-red-600 text-left max-w-[150px] truncate" title="${h.valorAnterior}">${h.valorAnterior || '--'}</td>
            <td class="p-3 text-emerald-600 text-left max-w-[150px] truncate font-bold" title="${h.valorNew}">${h.valorNew || '--'}</td>
        `;
        tbody.appendChild(tr);
    });
}

// Renderizado y control de la Bitácora de Auditoría en Tiempo Real
window.renderAuditoriaTab = async function () {
    const tbody = document.getElementById('audit-table-body');
    if (!tbody) return;

    tbody.innerHTML = `<tr>
        <td colspan="5" class="p-6 text-center text-slate-400">
            <i class="fa-solid fa-spinner fa-spin mr-2"></i>Cargando bitácora desde Supabase PostgreSQL...
        </td>
    </tr>`;

    try {
        const logs = window.DIATDataService ? await window.DIATDataService.getAuditLogs(100) : [];
        window._cachedAuditLogs = logs || [];
        const countBadge = document.getElementById('badge-count-auditoria');
        if (countBadge) countBadge.textContent = logs.length;
        window.filterAuditLogs();
    } catch (err) {
        tbody.innerHTML = `<tr>
            <td colspan="5" class="p-6 text-center text-red-500 font-bold">
                <i class="fa-solid fa-triangle-exclamation mr-2"></i>No se pudieron cargar los registros de auditoría: ${err.message}
            </td>
        </tr>`;
    }
};

window.filterAuditLogs = function () {
    const tbody = document.getElementById('audit-table-body');
    if (!tbody) return;

    const query = (document.getElementById('audit-filter-search')?.value || '').toLowerCase().trim();
    const typeFilter = document.getElementById('audit-filter-type')?.value || 'TODOS';

    const logs = (window._cachedAuditLogs || []).filter(l => {
        if (typeFilter !== 'TODOS' && l.tipo_evento !== typeFilter) return false;
        if (!query) return true;
        const u = (l.usuario_corto || '').toLowerCase();
        const n = (l.nombre_usuario || '').toLowerCase();
        const c = (l.convenio_id || '').toLowerCase();
        const d = (l.descripcion || '').toLowerCase();
        const t = (l.tipo_evento || '').toLowerCase();
        return u.includes(query) || n.includes(query) || c.includes(query) || d.includes(query) || t.includes(query);
    });

    if (logs.length === 0) {
        tbody.innerHTML = `<tr>
            <td colspan="5" class="p-8 text-center text-slate-400">
                <i class="fa-solid fa-folder-open text-2xl mb-2 text-slate-300 block"></i>
                No se encontraron eventos de auditoría coincidentes.
            </td>
        </tr>`;
        return;
    }

    const typeBadges = {
        'INICIO_SESION': '<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-emerald-100 text-emerald-800 border border-emerald-200"><i class="fa-solid fa-right-to-bracket mr-1"></i>Login Exitoso</span>',
        'LOGIN_FALLIDO': '<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-red-100 text-red-800 border border-red-200"><i class="fa-solid fa-circle-xmark mr-1"></i>Login Fallido</span>',
        'CAMBIO_PASSWORD': '<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-amber-100 text-amber-800 border border-amber-200"><i class="fa-solid fa-key mr-1"></i>Cambio Clave</span>',
        'RESTABLECER_PASSWORD': '<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-purple-100 text-purple-800 border border-purple-200"><i class="fa-solid fa-rotate-left mr-1"></i>Reset Clave</span>',
        'ACTUALIZACION_CONVENIO': '<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-blue-100 text-blue-800 border border-blue-200"><i class="fa-solid fa-pen-to-square mr-1"></i>Edición Convenio</span>',
        'REGISTRO_VISITA': '<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-teal-100 text-teal-800 border border-teal-200"><i class="fa-solid fa-helmet-safety mr-1"></i>Nueva Visita</span>',
        'ACTUALIZACION_VISITA': '<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-cyan-100 text-cyan-800 border border-cyan-200"><i class="fa-solid fa-clipboard-check mr-1"></i>Visita Editada</span>',
        'ELIMINACION_VISITA': '<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-rose-100 text-rose-800 border border-rose-200"><i class="fa-solid fa-trash-can mr-1"></i>Visita Eliminada</span>'
    };

    tbody.innerHTML = logs.map(l => {
        const d = new Date(l.fecha_hora);
        const fStr = isNaN(d) ? (l.fecha_hora || 'Reciente') : d.toLocaleString('es-CO', { dateStyle: 'short', timeStyle: 'medium' });
        const badge = typeBadges[l.tipo_evento] || `<span class="px-2 py-0.5 rounded-full text-[10px] font-extrabold bg-slate-100 text-slate-700">${l.tipo_evento}</span>`;
        const initials = (l.usuario_corto || 'SU').slice(0, 2).toUpperCase();
        const convChip = l.convenio_id ? `<span class="font-mono px-2 py-0.5 bg-slate-100 rounded text-slate-800 font-bold">${l.convenio_id}</span>` : '<span class="text-slate-300">-</span>';

        let detailsHtml = `<div class="font-semibold text-slate-800">${l.descripcion || ''}</div>`;
        if (l.detalles && typeof l.detalles === 'object' && Object.keys(l.detalles).length > 0) {
            const jsonStr = JSON.stringify(l.detalles);
            if (jsonStr !== '{}') {
                detailsHtml += `<div class="text-[10px] text-slate-400 font-mono mt-0.5 truncate max-w-md" title='${jsonStr.replace(/'/g, "&apos;")}'>${jsonStr}</div>`;
            }
        }

        return `<tr class="hover:bg-slate-50 transition">
            <td class="p-3 text-slate-500 whitespace-nowrap font-mono text-[11px]">${fStr}</td>
            <td class="p-3 whitespace-nowrap">
                <div class="flex items-center gap-2">
                    <span class="w-6 h-6 rounded-full bg-emerald-700 text-white text-[9px] font-black flex items-center justify-center">${initials}</span>
                    <div>
                        <div class="font-bold text-slate-800">${l.nombre_usuario || l.usuario_corto}</div>
                        <div class="text-[9.5px] text-slate-400 font-mono">${l.usuario_corto}</div>
                    </div>
                </div>
            </td>
            <td class="p-3 whitespace-nowrap">${badge}</td>
            <td class="p-3 whitespace-nowrap">${convChip}</td>
            <td class="p-3">${detailsHtml}</td>
        </tr>`;
    }).join('');
};

// =========================================================================
// MÓDULO DE ADMINISTRACIÓN GENERAL: SUPERVISORES, PERMISOS Y ROLES DIAT
// =========================================================================

// Pobla dinámicamente el selector de supervisores en la barra del ADMIN
function populateAdminSupervisorFilter() {
    const sel = document.getElementById('portal-admin-supervisor-filter');
    if (!sel) return;
    const currentVal = sel.value || 'ALL';
    sel.innerHTML = '<option value="ALL">🏛️ Todos los Supervisores (Consolidado Antioquia)</option>';

    const sups = new Set();
    if (typeof PORTAL_USERS === 'object') {
        Object.keys(PORTAL_USERS).forEach(k => {
            if (k !== 'ADMIN') {
                const name = PORTAL_USERS[k].supervisorExcelName || PORTAL_USERS[k].name;
                if (name) sups.add(name);
            }
        });
    }
    if (Array.isArray(rawData)) {
        rawData.forEach(r => {
            const s = (r['SUPERVISOR'] || '').trim();
            if (s && s !== 'ADMINISTRADOR' && s !== 'ADMIN') sups.add(s);
        });
    }

    const sorted = Array.from(sups).sort((a, b) => a.localeCompare(b));
    sorted.forEach(s => {
        const opt = document.createElement('option');
        opt.value = s;
        opt.textContent = `👤 ${s}`;
        sel.appendChild(opt);
    });

    sel.value = currentVal;
    sel.onchange = () => {
        renderSupervisorPortal();
        if (typeof window.filterSupervisorConvenios === 'function') {
            window.filterSupervisorConvenios();
        }
    };
}

// Renderiza el panel administrativo de gestión de supervisores y permisos
window.renderAdminSupervisoresPanel = function () {
    const tbody = document.getElementById('admin-supervisores-table-body');
    if (!tbody) return;

    const userKeys = Object.keys(PORTAL_USERS).filter(k => k !== 'ADMIN');
    let totalActive = 0;
    let totalCanEdit = 0;
    let totalCanVisits = 0;

    const supDataList = userKeys.map(k => {
        const u = PORTAL_USERS[k];
        const perms = window.DIATDataService ? window.DIATDataService.getSupervisorPermissions(k) : {
            active: true, canEditConvenios: true, canCreateVisits: true, canManagePhotos: true, canExportReports: true
        };
        const normName = normalizeSupervisorName(u.supervisorExcelName || u.name);
        const assignedRows = (rawData || []).filter(r => normalizeSupervisorName(r['SUPERVISOR']) === normName);
        const subregiones = [...new Set(assignedRows.map(r => r['SUBREGION']).filter(Boolean))];

        if (perms.active) totalActive++;
        if (perms.canEditConvenios) totalCanEdit++;
        if (perms.canCreateVisits) totalCanVisits++;

        return {
            key: k,
            user: u,
            perms: perms,
            assignedCount: assignedRows.length,
            subregiones: subregiones
        };
    });

    // Guardar en cache para filtrado instantáneo
    window._cachedSupervisoresList = supDataList;

    // Actualizar métricas KPI
    const setTxt = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
    setTxt('admin-kpi-total-supervisores', userKeys.length);
    setTxt('admin-kpi-active-supervisores', totalActive);
    setTxt('admin-kpi-edit-perm-count', totalCanEdit);
    setTxt('admin-kpi-visit-perm-count', totalCanVisits);
    const countBadge = document.getElementById('badge-count-supervisores');
    if (countBadge) countBadge.textContent = userKeys.length;

    window.filterAdminSupervisores();
};

// Filtra la tabla de supervisores por texto o estado de cuenta
window.filterAdminSupervisores = function () {
    const tbody = document.getElementById('admin-supervisores-table-body');
    if (!tbody) return;

    const query = (document.getElementById('admin-supervisor-search')?.value || '').toLowerCase().trim();
    const statusFilter = document.getElementById('admin-supervisor-status-filter')?.value || 'TODOS';

    const list = (window._cachedSupervisoresList || []).filter(item => {
        if (statusFilter === 'ACTIVO' && !item.perms.active) return false;
        if (statusFilter === 'INACTIVO' && item.perms.active) return false;
        if (!query) return true;

        const k = item.key.toLowerCase();
        const n = item.user.name.toLowerCase();
        const e = (item.user.email || '').toLowerCase();
        const r = item.subregiones.join(' ').toLowerCase();
        return k.includes(query) || n.includes(query) || e.includes(query) || r.includes(query);
    });

    if (list.length === 0) {
        tbody.innerHTML = `<tr>
            <td colspan="5" class="p-8 text-center text-slate-400">
                <i class="fa-solid fa-user-slash text-2xl mb-2 text-slate-300 block"></i>
                No se encontraron supervisores que coincidan con los criterios de búsqueda.
            </td>
        </tr>`;
        return;
    }

    tbody.innerHTML = list.map(item => {
        const p = item.perms;
        const activeBadge = p.active
            ? `<span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-extrabold bg-emerald-100 text-emerald-800 border border-emerald-300"><span class="w-1.5 h-1.5 rounded-full bg-emerald-600 animate-pulse"></span>Activa</span>`
            : `<span class="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-extrabold bg-rose-100 text-rose-800 border border-rose-300"><i class="fa-solid fa-ban text-rose-600"></i>Inactiva</span>`;

        const chip = (label, ok, icon, colorClass) => {
            return ok
                ? `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[9.5px] font-bold ${colorClass} border"><i class="fa-solid ${icon} text-[8.5px]"></i>${label}</span>`
                : `<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[9.5px] font-bold bg-slate-100 text-slate-400 border border-slate-200 line-through"><i class="fa-solid fa-xmark text-[8.5px]"></i>${label}</span>`;
        };

        const subregHtml = item.subregiones.length > 0
            ? `<div class="text-[10px] text-slate-400 truncate max-w-[180px] mt-0.5" title="${item.subregiones.join(', ')}">${item.subregiones.join(', ')}</div>`
            : `<div class="text-[10px] text-slate-400 italic mt-0.5">Sin convenios</div>`;

        return `
            <tr class="hover:bg-slate-50/80 transition">
                <td class="p-3.5 whitespace-nowrap">
                    <div class="flex items-center gap-3">
                        <div class="w-9 h-9 rounded-xl bg-slate-900 text-white flex items-center justify-center font-black text-xs shadow-sm">
                            ${item.user.initials || item.key.slice(0, 2)}
                        </div>
                        <div>
                            <div class="font-bold text-slate-900 flex items-center gap-1.5">
                                ${item.user.name}
                                <span class="font-mono text-[10px] text-slate-400 font-semibold">@${item.key}</span>
                            </div>
                            <div class="text-[11px] text-slate-500">${item.user.email || 'Sin correo asignado'}</div>
                        </div>
                    </div>
                </td>
                <td class="p-3.5 text-center whitespace-nowrap">
                    <span class="inline-block px-2.5 py-1 bg-emerald-50 border border-emerald-200 text-emerald-800 font-black text-xs rounded-lg">
                        ${item.assignedCount} convenios
                    </span>
                    ${subregHtml}
                </td>
                <td class="p-3.5 text-center whitespace-nowrap">
                    ${activeBadge}
                </td>
                <td class="p-3.5">
                    <div class="flex flex-wrap items-center gap-1.5 max-w-sm">
                        ${chip('Editar', p.canEditConvenios, 'fa-pen-to-square', 'bg-emerald-50 text-emerald-800 border-emerald-200')}
                        ${chip('Visitas', p.canCreateVisits, 'fa-helmet-safety', 'bg-blue-50 text-blue-800 border-blue-200')}
                        ${chip('Fotos', p.canManagePhotos, 'fa-camera', 'bg-purple-50 text-purple-800 border-purple-200')}
                        ${chip('Reportes', p.canExportReports, 'fa-file-export', 'bg-amber-50 text-amber-800 border-amber-200')}
                    </div>
                </td>
                <td class="p-3.5 text-center whitespace-nowrap">
                    <div class="flex items-center justify-center gap-1.5">
                        <button type="button" onclick="openEditPermissionsModal('${item.key}')"
                            class="px-3 py-1.5 bg-slate-800 hover:bg-slate-900 text-white rounded-lg text-xs font-bold transition flex items-center gap-1.5 shadow-sm hover:shadow"
                            title="Editar permisos operativos y estado de acceso">
                            <i class="fa-solid fa-sliders text-amber-400"></i>
                            <span>Permisos</span>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
};

// Abre el modal de configuración de permisos para un supervisor
window.openEditPermissionsModal = function (userKey) {
    const u = PORTAL_USERS[userKey];
    if (!u) return;

    const modal = document.getElementById('modal-edit-supervisor-permissions');
    if (!modal) return;

    const perms = window.DIATDataService ? window.DIATDataService.getSupervisorPermissions(userKey) : {
        active: true, canEditConvenios: true, canCreateVisits: true, canManagePhotos: true, canExportReports: true
    };

    const targetInp = document.getElementById('edit-perm-target-user');
    if (targetInp) targetInp.value = userKey;

    const av = document.getElementById('edit-perm-avatar');
    if (av) av.textContent = u.initials || userKey.slice(0, 2);

    const code = document.getElementById('edit-perm-user-code');
    if (code) code.textContent = '@' + userKey;

    const nameEl = document.getElementById('edit-perm-user-name');
    if (nameEl) nameEl.textContent = u.name;

    const emailEl = document.getElementById('edit-perm-user-email');
    if (emailEl) emailEl.textContent = u.email || 'Sin correo institucional';

    const setChecked = (id, val) => { const el = document.getElementById(id); if (el) el.checked = !!val; };
    setChecked('perm-toggle-active', perms.active);
    setChecked('perm-toggle-edit', perms.canEditConvenios);
    setChecked('perm-toggle-visits', perms.canCreateVisits);
    setChecked('perm-toggle-photos', perms.canManagePhotos);
    setChecked('perm-toggle-reports', perms.canExportReports);

    modal.classList.remove('hidden');
    modal.style.display = 'flex';
};

// Cierra el modal de permisos
window.closeEditPermissionsModal = function () {
    const modal = document.getElementById('modal-edit-supervisor-permissions');
    if (modal) {
        modal.classList.add('hidden');
        modal.style.display = 'none';
    }
};

// Guarda los permisos modificados en el modal
window.saveSupervisorPermissionsFromModal = async function (e) {
    if (e) e.preventDefault();
    const userKey = document.getElementById('edit-perm-target-user')?.value;
    if (!userKey) return;

    const getChecked = (id) => { const el = document.getElementById(id); return el ? el.checked : true; };
    const newPerms = {
        active: getChecked('perm-toggle-active'),
        canEditConvenios: getChecked('perm-toggle-edit'),
        canCreateVisits: getChecked('perm-toggle-visits'),
        canManagePhotos: getChecked('perm-toggle-photos'),
        canExportReports: getChecked('perm-toggle-reports')
    };

    const btn = document.getElementById('btn-save-supervisor-permissions');
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1.5"></i> Guardando...';
    }

    try {
        if (window.DIATDataService) {
            await window.DIATDataService.saveSupervisorPermissions(userKey, newPerms);
        }
        alertToast('Permisos Guardados', `Los permisos para ${PORTAL_USERS[userKey]?.name || userKey} fueron actualizados.`);
        window.closeEditPermissionsModal();
        if (typeof window.renderAdminSupervisoresPanel === 'function') {
            window.renderAdminSupervisoresPanel();
        }
    } catch (err) {
        console.error('[DIAT] Error al guardar permisos:', err);
        alertToast('Error al Guardar', 'No se pudieron actualizar los permisos: ' + err.message, 'error');
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '<i class="fa-solid fa-floppy-disk text-amber-400"></i><span>Guardar Permisos</span>';
        }
    }
};

// Acción administrativa: Restablecer contraseña a DIAT2026 de forma segura
window.triggerAdminPasswordReset = async function () {
    const userKey = document.getElementById('edit-perm-target-user')?.value;
    if (!userKey) return;
    const u = PORTAL_USERS[userKey];
    const supName = u ? u.name : userKey;

    if (!confirm(`¿Confirmas que deseas restablecer la contraseña de ${supName} (@${userKey}) a la clave provisional DIAT2026?\n\nEl supervisor tendrá que cambiar su clave de forma obligatoria en su siguiente inicio de sesión.`)) {
        return;
    }

    const btn = document.getElementById('btn-admin-reset-pw');
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1"></i> Restableciendo...';
    }

    try {
        if (typeof window.resetUserPassword === 'function') {
            const res = await window.resetUserPassword(userKey);
            if (res.success) {
                alertToast('Contraseña Restablecida', `La clave de ${supName} fue restablecida a DIAT2026.`);
            } else {
                alertToast('Error al Restablecer', res.error || 'No se pudo restablecer la contraseña.', 'error');
            }
        }
    } catch (err) {
        console.error('[DIAT] Error en reseteo de clave por admin:', err);
        alertToast('Error', err.message, 'error');
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '<i class="fa-solid fa-rotate-left"></i><span>Restablecer Clave</span>';
        }
    }
};

// Carga las alertas específicas del supervisor en el portal
function renderSupervisorAlertas(supervisorRows) {
    const container = document.getElementById('portal-alertas-list');
    if (!container) return;
    container.innerHTML = '';

    const today = new Date();
    let alertCount = 0;

    supervisorRows.forEach(row => {
        const id = String(row['CONVENIO']).trim();
        const municipio = row['MUNICIPIO'] || 'N/A';
        const fisico = row['FISICO_NORM'] || 0;
        const financiero = row['FINANCIERO_NORM'] || 0;

        let termStr = row['NUEVA FECHA DE TERMINACION'] || row['FECHA DE TERMINACION'];
        let termDate = parseCOPDate(termStr);
        const estStr = String(row['ESTADO CONVENIO'] || '').toLowerCase();
        const isLiquidado = estStr.includes('liquidado') || estStr.includes('resciliado');

        if (!isLiquidado) {
            let alertItem = null;
            if (termDate && termDate < today) {
                alertItem = {
                    type: 'vencido',
                    icon: 'fa-triangle-exclamation',
                    title: 'Convenio Vencido sin Liquidar',
                    desc: `El convenio venció el ${termStr} y continúa abierto sin acta de liquidación.`
                };
            } else if (termDate) {
                const msLeft = termDate.getTime() - today.getTime();
                const daysLeft = Math.ceil(msLeft / (1000 * 60 * 60 * 24));
                if (daysLeft <= 30) {
                    alertItem = {
                        type: 'proximos',
                        icon: 'fa-clock',
                        title: 'Próximo a Vencer',
                        desc: `Faltan ${daysLeft} días para la fecha límite de terminación (${termStr}).`
                    };
                }
            }

            if (financiero > fisico + 15) {
                alertItem = {
                    type: 'desfase',
                    icon: 'fa-chart-pie',
                    title: 'Desfase Financiero Crítico',
                    desc: `El avance financiero (${financiero.toFixed(1)}%) supera al físico (${fisico.toFixed(1)}%) en más del 15%.`
                };
            }

            const suspVal = parseNum(row['SUSPENSION(MESES)'] || row['SUSPENSIÓN(MESES)'] || row['SUSPENSION (MESES)'] || 0);
            if (estStr.includes('suspendido') && suspVal >= 3) {
                alertItem = {
                    type: 'suspension',
                    icon: 'fa-pause',
                    title: 'Suspensión Prolongada',
                    desc: `El convenio acumula ${suspVal} meses en estado suspendido.`
                };
            }

            if (alertItem) {
                alertCount++;
                const itemDiv = document.createElement('div');
                itemDiv.className = `alert-feed-item alert-${alertItem.type} flex justify-between items-center gap-4`;
                itemDiv.innerHTML = `
                    <div class="flex items-start gap-3">
                        <div class="alert-item-icon ${alertItem.type}">
                            <i class="fa-solid ${alertItem.icon}"></i>
                        </div>
                        <div>
                            <h4 class="alert-item-title">${alertItem.title}</h4>
                            <p class="text-xs text-slate-500 leading-relaxed mt-0.5">${alertItem.desc}</p>
                            <div class="alert-item-meta mt-1.5">
                                <span class="alert-item-tag"><i class="fa-solid fa-hashtag"></i>${id}</span>
                                <span class="alert-item-tag"><i class="fa-solid fa-location-dot"></i>${municipio}</span>
                            </div>
                        </div>
                    </div>
                    <div>
                        <button type="button" class="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-lg text-xs uppercase tracking-wider transition-all" onclick="openEditConvenioModal('${id}')">
                            Gestionar
                        </button>
                    </div>
                `;
                container.appendChild(itemDiv);
            }
        }
    });

    if (alertCount === 0) {
        container.innerHTML = `
            <div class="flex flex-col items-center justify-center py-8 text-center text-emerald-600 bg-emerald-50/50 rounded-xl border border-emerald-100 p-4">
                <i class="fa-solid fa-circle-check text-2xl mb-2"></i>
                <h4 class="text-xs font-bold uppercase tracking-wider">¡Todo al día!</h4>
                <p class="text-[11px] text-emerald-600/80 mt-0.5">Tus convenios no presentan alertas de riesgo contractual vigentes.</p>
            </div>
        `;
    }
}

